INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conquest of Elysium 2', 'Conquest of Elysium is a fantasy game where you and your friends take control of a powerful warlord or wizard and struggle for total control of the continent. Up to eight players may participate and the computer can control any free players. The game is turn-based so you only need one computer to play the game with up to seven friends. Conquest of Elysium was originally released in 1996 for the Atari Falcon line of computers. The number "II" denotes the version number.' FROM games WHERE igdb_id = 326798 ON CONFLICT (game_id, language_code) DO NOTHING;
