INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Koi ha Balance: Tatoeba K-kun no Tabou na Ichinichi-hen', 'Koi ha Balance: Tatoeba K-kun no Tabou na Ichinichi-hen is a Downloadable game for the Satellaview that was first broadcast on January 27, 1996. The game is a board game and it features, among other characters, both Gaspar and Johnny from the earlier Square title, Chrono Trigger. It is a board game about love-related topics presented in an humorously over-the-top manner.' FROM games WHERE igdb_id = 134463 ON CONFLICT (game_id, language_code) DO NOTHING;
