INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Travel Junction', 'Hero fails to find a job in a major tour company. Eventually, he gets a job in a very small tour company on the verge of bankruptcy only containing four people with him. Their last hope is barely known southern island that no big tourist company holds. Hero and company president''s daughter go there as guides alongside a tourist group of six women.' FROM games WHERE igdb_id = 335859 ON CONFLICT (game_id, language_code) DO NOTHING;
