INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-fire-pro-wrestling-x-premium', 38420, '1996-04-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49el.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Fire Pro Wrestling X Premium', 'In this final appearance of Fire Pro series on 16-bit consoles, the usual roster of over 150 wrestlers from several wresting promotions worldwide including several styles from Shoot or Pancrase to American and Lucha are joined by 80 Create-a-wrestler slots, plus secret wrestlers such as legends Gotch or Thesz or the roster of Blazing Tornado. While all fighters have fictional names, a lot of them are perfectly recognizable by their attire, stance and style. The CAW mode allows the player to create a wrestler from scratch, setting how they look (choosing face, size, clothing and setting colours) and fight, with several styles and stances available, as well as over 500 moves, each more suitable for certain styles and skills. To make them fight more realistically when controlled by the AI, the CAW mode also allows one to set move priorities. Five game modes are available, including World Championship (single and tag), Battle Royale, 5-man Elimination Mode, League Battle and the One Night Dream Match. There are several referees available (each with their own quirks) and variant rules, from allowing fighting outside the ring without count-out (or disallowing it) to the disabling of disqualifications from illegal moves.' FROM games WHERE igdb_id = 38420 ON CONFLICT (game_id, language_code) DO NOTHING;
