INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kick Off 96', 'Kick Off 96 gives you the chance to take part in the European Championships in England 1996. Kick Off 96 can be played with several perspectives, including overhead and isometric, and offers the same pacey gameplay that made its predecessors famous. If Euro 96 isn''t enough you could play with 49 international teams plus 750 club teams, totalling 15.000 real players with varied skill levels. If that''s still not enough, you can also create your own leagues and teams.' FROM games WHERE igdb_id = 94330 ON CONFLICT (game_id, language_code) DO NOTHING;
