INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Creator', 'Made by the Electronic Arts Victor company, Dungeon Creator is a first person dungeon creator tool in the vein of RPG Maker. Packed in with a sample dungeon to play yourself as well as the limited edition with 10 extra dungeons made by collaborating magazine publications, there''s a ton of fun to be had both creating your own dungeons as well as playing through the existing ones.' FROM games WHERE igdb_id = 394965 ON CONFLICT (game_id, language_code) DO NOTHING;
