INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Heroes IV: Akai Shizuku', 'The Legend of Heroes IV: Akai Shizuku is the fourth entry in Falcom''s Legend of Heroes RPG series and the second installment in the "Gagharv Trilogy." The game was originally developed and published by Falcom for the NEC PC-98 on March 24, 1996 with ports being released for the PlayStation in 1998 and PC in 2000.' FROM games WHERE igdb_id = 240542 ON CONFLICT (game_id, language_code) DO NOTHING;
