INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astrocounter of Crescents', 'In 2095, the world is shaken by a war between the SpaceWorld Community and the Earth Liberation Front over control over Earth and orbit. Also two corporations compete in the field of space colonization. The player takes the role of the mech pilot Lin Seo who works for one of these corporations - but soon things go very wrong..' FROM games WHERE igdb_id = 50080 ON CONFLICT (game_id, language_code) DO NOTHING;
