INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doraemon: Nobita to Fukkatsu no Hoshi', 'Doraemon: Nobita to Fukkatsu no Hoshi is a side-scrolling action platformer, and one of the many titles based on the long-running children''s cartoon. The game is divided into short platform stages, each with a specific objective or goal that must be completed to move on. Between stages, there are voiced visual novel-style sequences which move the story forward. There are sometimes choices available in these sections, which can affect which stage the player reaches next.' FROM games WHERE igdb_id = 91772 ON CONFLICT (game_id, language_code) DO NOTHING;
