INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby no Omochabako: Arrange Ball', 'In Kirby''s Toy Box - Arranging Balls, the player is given the goal of launching spherical Kirbys into the nine holes occupied by Mr. Frostys. The player is given a certain number of Kirbys to launch, and the game ends when he/she runs out of Kirbys to shoot. The player can choose how much power to put into each shot. Points are awarded if the player lands three Kirbys in a row—the more rows the player completes, the more points he/she will earn. Like every other sub-game in Kirby''s Toy Box, this game could only be downloaded by the Satellaview during the brief period it was broadcast.' FROM games WHERE igdb_id = 134455 ON CONFLICT (game_id, language_code) DO NOTHING;
