INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Living Books: The Berenstain Bears in the Dark', '"The Berenstain Bears in the Dark" is an interactive educational game based on the book of the same name. It follows Brother Bear reading a scary story to Sister Bear, leading her to fear the dark. Papa Bear helps Sister Bear realize it''s just her imagination, while Brother Bear eventually becomes afraid of the dark too. The game features two play modes, "Read To Me" and "Let Me Play," as well as bonus games like "Animal Match" and "Picture Jumble."' FROM games WHERE igdb_id = 254866 ON CONFLICT (game_id, language_code) DO NOTHING;
