INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('black-viper', 14311, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/pzpqdv3te9klx1x47hb6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Viper', 'Black Viper takes inspiration from games such as Fire and Forget and Chase H.Q., replacing the fast car with an armed motorcycle. As usual, this game takes place after a terrible nuclear war, with you playing as the son of a lost freedom fighter. The freedom fighters try to recapture the remaining cities from the mercenaries acting on behalf of the underground people who instigated the war in the first place. To do this, you must travel from city to city on the open roads, arriving within a given time frame. This is difficult due to the crowded roads, but luckily you can blow up most other vehicles with your gun. As the game progresses, enemy vehicles become harder, requiring more shots to be taken out. Luckily, your bike may be upgraded in the shop between levels. Black Viper has a certain arcade-ish look to its graphics, a jukebox for choosing soundtracks, and comes in both OCS and AGA versions.' FROM games WHERE igdb_id = 14311 ON CONFLICT (game_id, language_code) DO NOTHING;
