INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('threshold-rpg', 206985, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vra.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Threshold RPG', 'Threshold is a high fantasy, real-time, multi-player, online role playing game. Once you step across the Threshold you will be absorbed by the rich, detailed, highly developed role playing atmosphere that comprises this fantasy realm. You become the hero, the heroine, or even the villain depending on your character and your imagination. On Threshold, role playing is required and enforced. This policy creates and preserves Threshold''s top notch role playing environment. Although there are places to communicate "out of character" within the game (after all, it is nice to get to know the people you are gaming with), outside of such areas players stay completely in character. Threshold RPG opened to the public in June of 1996. It is the oldest role playing enforced MUD currently in operation. Available 24 hours a day, 365 days a year, this exciting gaming environment is home to thousands of players from all over the world. These players are indeed what makes Threshold RPG a truly unique and marvellous gaming community.' FROM games WHERE igdb_id = 206985 ON CONFLICT (game_id, language_code) DO NOTHING;
