INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('casual-romance-club', 73471, '1996-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7typ.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casual Romance Club', 'You are a teenage boy in high school. You join the Casual Romance Club in order to meet other people and perhaps find love. There are twelve girls you can approach, each one possessing her own unique beauty and personality. Use your time and efforts wisely and you may just get yourself more than a casual romance... You are given a month to shop around and win somebody''s love, after which you''ll ask the girl of your choice to keep seeing you even after the club adjourns. Each game day starts at the Starry Sky restaurant, with the club notebook laid out for you. The club notebook has the lowdown on all the girls -- their basic statistics, pictures, horoscopes, likes, dislikes, etc. The girls also record their thoughts and reactions on daily events next to their horoscopes, so reading the club notebook can prove vital to your success.' FROM games WHERE igdb_id = 73471 ON CONFLICT (game_id, language_code) DO NOTHING;
