INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bishoujo Senshi Sailor Moon Super S: Zenin Sanka!! Shuyaku Soudatsusen', 'This game is the sequel and an update to Sailor Moon S: Jougai Rantou!? Shuyaku Soudatsusen. The Sailor Senshi are fighting to choose a new leader. After defeating an enemy, Sailor Moon was teased by Sailor Chibi Moon and Sailor Mars, who called her undependable. The rest of the Sailor Senshi then decided to have a contest to choose a new leader. This game is based on the popular Anime series "Sailor Moon" and was released only for the japanese Super Famicom.' FROM games WHERE igdb_id = 42341 ON CONFLICT (game_id, language_code) DO NOTHING;
