INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shinpi-no-sekai-el-hazard', 109078, '1996-03-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9t5l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3l7s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shinpi no Sekai El-Hazard', 'Shinpi no Sekai: El-Hazard is based off of an anime with the same title. The game plays like an enhanced visual novel which is fully voice-acted and displays protagonist and other characters on the screen during dialogues. Event scenes and animations are quite common, and character poses depicting their current disposition is displayed in portrait images which are also animated. Unlike typical visual novels where the player is limited to dialogue and choices, players can explore various locations on the map and try to perform actions outside the dialogue window, such as initiating a talk to other characters, or look around the area or go someplace else.' FROM games WHERE igdb_id = 109078 ON CONFLICT (game_id, language_code) DO NOTHING;
