INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('neon-genesis-evangelion-1st-impression', 69709, '1996-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2wlk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgpfm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neon Genesis Evangelion: 1st Impression', 'The first Evangelion video game, released for the Sega Saturn in 1996, shortly after the TV series''s run. The story is set after the episode ASUKA STRIKES!, with Shinji badly injured and suffering amnesia as the result of an Angel battle and needing to retrain (by sparring with Asuka in Unit-02) and having to defeat the Angel to regain his memories. The game features RPG elements and FMV clips for combat; most of the animation is original to 1st Impression (with the voices of the original Evangelion voice actors and some other content recycled from the TV series).' FROM games WHERE igdb_id = 69709 ON CONFLICT (game_id, language_code) DO NOTHING;
