INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Date: Doki-doki Kokuhaku Daisakusen', 'Magical Date is a skill game and dating sim published by Taito in 1996 for arcade and PlayStation. In this game, the player picks one of three possible girls to date and then starts off in a square as in a board game, proceeding to other squares which have different mini games. At junction points the player is asked questions about their date and has to pick the correct answer, or she will become upset. Released in October 1996 in Japan only. The subtitle of this game translates from Japanese as ''Cruel Heartthrob Tactics''.' FROM games WHERE igdb_id = 360723 ON CONFLICT (game_id, language_code) DO NOTHING;
