INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tenchi Muyo! Ryo-Ohki FX', 'Tenchi Muyō! Ryō-ōki FX includes Tenchi Muyō! Ryō-ōki with slightly better graphics (full-screen pictures instead of framed ones), and a whole new chapter, which is dedicated to officers of the Galaxy Police. The new chapter centers around the green-haired Hakua, who works for Mihoshi Kuramitsu, one of the game''s main characters, and Detective Kiyone Makibi, Mihoshi''s ex-partner.' FROM games WHERE igdb_id = 123079 ON CONFLICT (game_id, language_code) DO NOTHING;
