INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skipper & Skeeto: Tales from Paradise Park', 'Danish point-and-click adventure game with some edutainment content. The first game in Skipper and Skeeto -franchise. A witch has stolen the good fairy''s magic wand and Skipper and Skeeto must help get it back. The game is set in a park where the player helps various animals in order to move forward in the story. Game features minigames with some educational content, for example locating countries on a map or telling the time.' FROM games WHERE igdb_id = 18992 ON CONFLICT (game_id, language_code) DO NOTHING;
