INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bakumatsu Kourinden Oni', 'Bakumatsu Korinden Oni is a Role-Playing game, developed by Pandora Box and published by Banpresto, which was released in Japan in 1996. This is the seventh title in the ONI series and is set in Japan approximately 670 years after the previous title, Kishin KouRinden ONI. The two titles share the same world and common characters. It is also notable for the appearance of historical figures such as the Shinsengumi, Ryoma Sakamoto, and Yoshinobu Tokugawa.' FROM games WHERE igdb_id = 15897 ON CONFLICT (game_id, language_code) DO NOTHING;
