INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Moto X', 'International Moto X is an off-road motorcycle racing game for the PS1 released in PAL regions. Wrestle with sheer drops, tackle vertical climb-outs and plunge down muddy banks. International Moto X is the most realistic and exhilarating off-road motorcycle simulation game ever! With its own unique 3D engine, it offers its players realistic bike handling, break-neck speeds and unrivalled graphics.' FROM games WHERE igdb_id = 58959 ON CONFLICT (game_id, language_code) DO NOTHING;
