INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sega-worldwide-soccer-97', 45498, '1996-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/yvgglx7116xg4ry3rnyu.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Worldwide Soccer ''97', 'Sega Worldwide Soccer 97 (known as Sega Worldwide Soccer PC for the PC and Victory Goal Worldwide Edition in Japan) is a football video game by Sega released for the Sega Saturn in 1996. It is the successor to Victory Goal and was later followed by three more titles: Sega Worldwide Soccer ''98 still on the 32-bit console and two editions of Sega Worldwide Soccer 2000, the second being Sega Worldwide Soccer 2000 Euro Edition for the Dreamcast. Sega Worldwide Soccer 97, produced by Sega themselves was one of the killer apps in the peak of popularity for the console. It was preceded by Victory Goal, an already ageing football game (one of the debut titles of the console). The game featured international teams and league, play-off and tournament modes. Although it used fictional player names (due to the lack of a license), the non-volatile memory of the Saturn allowed editing of names. The team kits were as close to the official 1996 kits as possible. The gameplay was also highly praised, and was the top-rated football game until ISS 64 was released one year later. Sega Worldwide Soccer 97 was later ported to the PC, under the title of Sega Worldwide Soccer PC.' FROM games WHERE igdb_id = 45498 ON CONFLICT (game_id, language_code) DO NOTHING;
