INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Step On It!', 'A game with similarities to Lode Runner, the player controls a rudimentary stick figure character with the ability to add and remove blocks on the diagnal. The main goal of each level is to avoid enemies and pick up all the items available. This is a good mix of puzzle and platforming. The game also includes a co-op mode where you can play with a friend on the same keyboard' FROM games WHERE igdb_id = 343001 ON CONFLICT (game_id, language_code) DO NOTHING;
