INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road & Track Presents: The Need for Speed - Special Edition', 'Road & Track Presents: The Need for Speed - Special Edition is a 1996 retail re-release of The Need for Speed for PC which includes several improvements over the original 1995 PC release. It introduced support for Microsoft Windows 95, whilst capable of running on Microsoft DOS, and several improvements to its rendering engine as well as two additional tracks. The complete soundtrack playing during races was also made available on the Special Edition. This feature was previously only in the PlayStation and Sega Saturn releases.' FROM games WHERE igdb_id = 209107 ON CONFLICT (game_id, language_code) DO NOTHING;
