INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superman: The Mysterious Mr. Mist', 'A mysterious creature rises from the depths of the Earth to capture a new queen for his people, and he''s got his eyes on Lois Lane. His evil powers allow him to transform into any human shape, causing total confusion. Will Superman save Lois from the cluthces of the Mysterious Mr. Mist? - Spectacular rare interactive CDROM multimedia comic book!' FROM games WHERE igdb_id = 73324 ON CONFLICT (game_id, language_code) DO NOTHING;
