INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Teaches Typing 2', 'Mario Teaches Typing 2 is the sequel to Mario Teaches Typing. It includes several new features, including a certificate of achievement, a keyboard that is color-coded for easy reference, an on-screen keyboard, specially customizable lesson plans, and new levels. Additionally, Mario''s face also makes small talk with the player throughout the levels. Many of Mario''s face''s antics in this game are cultural references. This is also the last educational Mario game to be released.' FROM games WHERE igdb_id = 46445 ON CONFLICT (game_id, language_code) DO NOTHING;
