INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Jam Extreme', 'NBA Jam Extreme features many of the top players from the 1996–97 NBA season. Rosters accurate as of September 11, 1996, with some notable omissions. Chief among them were Michael Jordan, Charles Barkley and Shaquille O''Neal. Jordan and O''Neal had contracts with Electronic Arts that resulted in the Jordan game Chaos in the Windy City and O''Neal appearing in Shaq-Fu and the NBA Live games. Barkley had signed a deal with Accolade to appear in its Barkley Shut Up and Jam! games.' FROM games WHERE igdb_id = 40205 ON CONFLICT (game_id, language_code) DO NOTHING;
