INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Bowling', 'A 2D arcade bowling game developed and released by International Games System. Cabinets came in two styles: traditional joystick and buttons, or trackball. Players must get a certain number of points in the first five frames to unlock the next five frames. Completing 10 frames with a good score unlocks Special mode, where groups of pins are set up in unique patterns and must be knocked down in a single throw. Not to be confused with Ten Pin Alley for the Sony Playstation and Sega Saturn, whose Japanese release was also named Virtua Bowling.' FROM games WHERE igdb_id = 354530 ON CONFLICT (game_id, language_code) DO NOTHING;
