INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'In the Intrigue of the Ratings', 'A title which focused on the incompetent detective Elimelech Egoz (voiced by Moshe Ferster), who goes on holiday at the fictional Nofei Hadera Hotel only to be greeted by a bizarre murder case. The game contained intertextuality, inside jokes, irony, and cynicism. In the Interest of Ratings received negative reviews in the press, including in Internet Captain (קפטן האינטרנט), the technology/multimedia branch of the leading Israeli newspaper Haaretz; however it received positive reviews in youth-oriented newspapers. Ultimately the game was relatively popular, though it was not financially successful. But it led the duo to decide to try to develop a second video game, which would become Piposh, under their new development company Guillotine (גיליוטין).' FROM games WHERE igdb_id = 145694 ON CONFLICT (game_id, language_code) DO NOTHING;
