INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nemesis-the-wizardry-adventure', 2500, '1996-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co63a9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/c5ssgmo2mlaf2mcejlxj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nemesis: The Wizardry Adventure', 'A new world of Wizardry. The horror that destroyed an entire civilization has returned. It has only one target: You. An ancient evil stalks you. The age-old Nitherin talismans are your only hope. Yet these talismans also contain a ferocious energy, the ultimate power of destruction... Quite possibly... yours. Enter Nemesis, a world of mystery, magic and terror. Nemesis invites you into a spectacular world spanning 5 CDs. With stunning 3D graphics that take you into a whole new realm. Responsive, real-time combat. A full stereo soundtrack. Rich digital speech. And an easy to use interface that won''t get in the way of your adventure. As you explore the forests, castles and hidden ruins of Nemesis, you''ll test your wits as well as your sword. Unravel clues to unlock the mysteries of fiendish traps and mystic devices in the only adventure earning the mark of Wizardry. Experience the only adventure game to bring you the epic fantasy that is Wizardry.' FROM games WHERE igdb_id = 2500 ON CONFLICT (game_id, language_code) DO NOTHING;
