INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goosebumps: Escape from Horrorland', 'Goosebumps: Escape from Horrorland is the interactive sequel to R.L. Stine''s kids'' horror novel, One Day at Horrorland. You and Lizzy, her brother Luke, and his friend Clay are once again trapped in Horrorland, a sinister, scary "theme park." When Luke and Clay are captured, you and Lizzy must find them and escape from the park with your lives. However, you must go up against a mummy, a werewolf, Dracula, and many more monsters in order to escape.' FROM games WHERE igdb_id = 79276 ON CONFLICT (game_id, language_code) DO NOTHING;
