INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('x-men-mojo-world', 46326, '1996-09-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4eb5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq0cz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men: Mojo World', 'X-Men: Mojo World, a video game released in 1996 for the Game Gear system, features Wolverine and Rogue as the initial playable X-Men, with Gambit, Cyclops, Havok, and Shard unlockable later on. The game utilizes the same engine as its predecessor, X-Men: Gamesmaster''s Legacy, and was also launched for the Master System in Brazil by Tec Toy. Set in a dystopian future, Mojo hosts a deadly TV show where participants engage in fights to the death. Having imprisoned certain X-Men from the past, Mojo aims to recreate their most epic battles. Wolverine and Rogue must enter the game, rescue their friends, and ultimately defeat Mojo to return home. Players start by choosing either Wolverine or Rogue. As each new level is conquered, additional X-Men become available, starting with Gambit, followed by Cyclops, Havok, and finally Shard. If any X-Men perish, the player must restart the level, selecting from the remaining characters. When all X-Men are defeated, the game concludes. Each character can activate their unique power at will. Wolverine employs his claws, Rogue can fly, Gambit hurls explosive cards, Cyclops unleashes optic blasts, Havok fires plasma blasts, and Shard utilizes energy blasts. Characters have both an energy meter and a power meter, depleting when they take hits or use their powers. Energy and power-restoring items can be found throughout the game. The gameplay primarily revolves around navigating through six levels, with each level culminating in a boss battle against well-known comic characters such as Magneto, Fitzroy, a Sentinel, and others.' FROM games WHERE igdb_id = 46326 ON CONFLICT (game_id, language_code) DO NOTHING;
