INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart Adventures 4th Grade: Haunted Island', 'JumpStart Adventures 4th Grade: Haunted Island is a JumpStart game that was made by Knowledge Adventure on December 2, 1996. It was later re-released on November 24, 1997 with Map Scroll and Ms. Grunkle''s Hat level indicator added. As the title suggests, the game is intended to teach a fourth grade curriculum. It was later replaced by JumpStart Adventures 4th Grade: Sapphire Falls in 1999. In its original release, it contained KnowledgeLand as a bonus disc.' FROM games WHERE igdb_id = 129146 ON CONFLICT (game_id, language_code) DO NOTHING;
