INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gulliver in the Land of Giants', 'Gulliver in the Land of Giants is a Russian educational game based on the second part of Jonathan Swift''s satirical masterpiece best known as "Gulliver''s Travels". The game contains several modes: - Animated audio book. - Game (Boy or Girl), 2 different kind of games depending on which gender chosen. - English lessons for digits or colors. - Painting book. - Audio drama, which is the same as animated audio book but with no visuals.' FROM games WHERE igdb_id = 300339 ON CONFLICT (game_id, language_code) DO NOTHING;
