INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twilight Syndrome Kyuumei-hen', 'The gameplay in this sequel is identical to that of the previous entry: the player navigates the digitized images of the girls over 2D backgrounds in a side-scrolling/third-person perspective manner, searching for clues, triggering scenes, and choosing responses and/or actions when prompted by the narrative. It consists of six independent scenarios, and the numbering of the scenarios is a continuation from the previous title.' FROM games WHERE igdb_id = 65454 ON CONFLICT (game_id, language_code) DO NOTHING;
