INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nightruth-number-01-yami-no-tobira', 98291, '1996-08-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaswj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4mm3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightruth #01: Yami no Tobira', 'Nightruth is a visual novel-style adventure game following the adventures of a team of high school students who use their supernatural abilities to to investigate paranormal events. The game plays out as standard for this type of game, consisting of voiced and illustrated story scenes with occasional player choices; these choices branch off via player choice into one of three different storylines, each of which has multiple possible endings. This PlayStation version of Nightruth includes the complete original game along with a new additional fourth scenario as well as two bonus discs: a "Making of" disc that includes production artwork and voice actor interviews, and a music CD containing the game''s theme song.' FROM games WHERE igdb_id = 98291 ON CONFLICT (game_id, language_code) DO NOTHING;
