INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('archimedean-dynasty', 2197, '1996-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ktd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8rq3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Archimedean Dynasty', 'The all consuming darkness has you battle-scarred submarine in a vice-like grip. As you navigate your sub through enemy waters, the only thing that protects you from a cold and premature death is six inches of solid steel. As if life itself, 5,700 metres below the ocean surface wasn’t difficult enough, the threat of impending conflict is about to challenge your very existence… In the distance, a glimmer of light pierces the darkness and shock waves begin to roll your craft. An unknown object descends upon you. Systems indicate Torpedo! You act immediately to avoid destruction and lock your sights on the incoming torpedo. You release a Ripper missile and begin your descent, but you must go faster. DIVE! DIVE! DIVE! The predecessor to the AquaNox series, Archimedean Dynasty is a submarine-simulation set in a post-apocalyptic world on the ocean floor. Assuming the role of mercenary, Emerald “Dead Eye” Flint, you must navigate the dangers that lurk below, including corrupt conglomerates, fanatical cults and cut-throat pirates. With a rich and atmospheric open-world, compelling narrative and dialogue interaction, and a deep customisation and combat system that rewards tactical thinking, Archimedean Dynasty is a submersive experience for nautical adventurers that like to talk the talk and sail the sail.' FROM games WHERE igdb_id = 2197 ON CONFLICT (game_id, language_code) DO NOTHING;
