INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HIND: The Russian Combat Helicopter Simulation', 'Hind is a combat flight simulation game released by Digital Integration in 1996 for MS-DOS compatible operating systems and Microsoft Windows. It is the successor to Apache. The game features the Soviet military Mi-24V Hind-E helicopter. It came with a detailed 99 page printed manual explaining the basics of helicopter flight and control, along with the specific traits of the Mi-24 helicopter and its weaponry.' FROM games WHERE igdb_id = 747 ON CONFLICT (game_id, language_code) DO NOTHING;
