INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shutokou-battle-gaiden-super-technic-challenge', 208469, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4yml.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schtu9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shutokou Battle Gaiden: Super Technic Challenge', 'Shutokou Battle Gaiden: Super Technic Challenge is a Racing game, developed by Mitsui & Co. and published by MediaQuest, which was released in Japan in 1996. It features 25 licensed vehicles. The gameplay consists of drifting your vehicle with arcade-like handling in drift zones and recieving scores based on the angle, length and speed of the players''s drift. Events are set up as a 1 v 1 battle between the player and a CPU, with the winner being whoever has the highest drift score at the end of the lap.' FROM games WHERE igdb_id = 208469 ON CONFLICT (game_id, language_code) DO NOTHING;
