INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic''s Schoolhouse', 'Sonic''s Schoolhouse is an educational computer game that teaches young learners mathematics, reading, and spelling, released in 1996 with collaboration of Sega and Orion Pictures Corporation. In addition, players can earn access to two mini-games (a collect-the-rings game and a match-the-statues game) and a "field trip" section which gives them numerous facts on the various animals in the game (through video clips).' FROM games WHERE igdb_id = 52750 ON CONFLICT (game_id, language_code) DO NOTHING;
