INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkness', 'Darkness is a Korean action RPG released in 1996 by DOT&BIT for PC DOS. The game requires information from the manual to play past the initial zone as it uses a code at the bottom of the first screen to tell the player which order to hit a set of statues in order to move on. It has English button prompt instructions and UI elements but all the story and character text is in Korean.' FROM games WHERE igdb_id = 145589 ON CONFLICT (game_id, language_code) DO NOTHING;
