INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoyo''s Puzzle Park', 'YoYo''s Puzzle Park (released as "Gussun Paradise" in Japan) is a puzzle platform game featuring some sixty platform-filled levels similar to Bubble Bobble. The player (as Guss or Yodie) can hop around on them, while avoiding the enemies that crowd the platforms. ... In the multi-player mode, you can fight against your friends in a two-player deathmatch game.' FROM games WHERE igdb_id = 44718 ON CONFLICT (game_id, language_code) DO NOTHING;
