INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nirvana-x-rom', 142144, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2nkg.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nirvana X-ROM', 'Nirvana X-ROM is the companion game to the Italian SciFi film Nirvana directed by Gabriele Salvatores. It is set after the events of the film: VR game developer Jimi Dini has wiped the source code of his latest game Nirvana, thus releasing its protagonist Solo from his virtual prison. However, portions of the game still survive in Jimi''s archives, creating a potential risk of Nirvana being re-assembled. The player is called upon to investigate Jimi''s house and archives in search for the lingering game code and destroy it.  The gameplay is a mixture of puzzle-solving and exploration viewed from the player''s perspective. The location view can be freely rotated by moving the mouse and several objects are clickable, often giving access to secret rooms. The bottom bar icons offer several actions such as using scanners, connecting to the network and communicating with the artificial intelligence that powers Jimi''s house. Many solutions to the puzzles are found by sifting through Jimi''s archives, which contain audio, images and clips from the film, as well as program code and other digital objects' FROM games WHERE igdb_id = 142144 ON CONFLICT (game_id, language_code) DO NOTHING;
