INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('surf-m-up', 77331, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2un0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc945u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Surf ''m Up!', 'Distributed freely to students, Surf ''m Up is a little Kaboom!-inspired game by Dutch beer brewer Dommelsch.  The premise is simple: four cranes of a beer tender are spilling droplets and you, an empty beer glass, must collect each droplet. Controlled by keyboard or mouse, the game is a test of reflexes. Each collected droplet gives 5 points; 45 points will get you to the next section; after three sections you will progress to the next increasingly harder level.  Missing too many droplets will cause the beer glass to slip. Watch out for falling sugar cubes, peanuts, matchsticks and darts - you can only withstand them three times. Also beware of a little green caterpillar who tries to hinder your progress in all manners possible. Help comes in the form of a bell announcing ''happy hour''-mode - making your beer glass invulnerable for a couple of seconds. Another help is a sponge appearing from time to time. Jumping on it cleans all spilled droplets.  Users were encouraged to save their highscores on a blank disk and send them, accompanied with a slogan, to Dommelsch. The ten best highscorers would receive video game prizes.' FROM games WHERE igdb_id = 77331 ON CONFLICT (game_id, language_code) DO NOTHING;
