INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uchuu Goushouden: Bakuretsu Akindo', 'Bakuretsu Akindo Uchuu Goushouden is a sugoroku board game (Japanese backgammon) that takes its players to the universe. Gameplay offers a high degree of freedom. Player can choose to make money slowly by taking up ordinary jobs, or take a risk and make a fortune at one stroke.' FROM games WHERE igdb_id = 376994 ON CONFLICT (game_id, language_code) DO NOTHING;
