INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gus-goes-to-cyberstone-park', 209786, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4zk5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq37a.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gus Goes to CyberStone Park', 'Gus Goes to Cyberstone Park is an educational game for children between three and eight. The player can explore five locations and trigger animations by clicking on items on screen. Gus'' three buddies are hiding in each screen and speak/sing to the player when found. Each location additionally has an activity: Trees: The player has to navigate Gus through a top-down maze. Mountains: The player has to solve equations (addition and subtraction) in four difficulty levels. On the easiest level, the nine digits have to be clicked on in the correct order. Lake: Sorting animals into their correct habitat (earth, forest or water) River: Animals float on the river and each of them holds a sign with a letter. The player has to click on the starting letter of the given word. There are four difficulty levels. Camp: The player is given an incomplete campfire story and has to complete them by dragging icons on the blank spaces. There are no right or wrong choices.' FROM games WHERE igdb_id = 209786 ON CONFLICT (game_id, language_code) DO NOTHING;
