INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bridge-deluxe-2-with-omar-sharif', 85921, '1996-03-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4sx4.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bridge Deluxe 2 With Omar Sharif', 'Whether you''re a beginning bridge player or an expert, Bridge Deluxe 2 with Omar Sharif is the game you have been waiting for. Internationally renowned actor and master bridge player Omar Sharif brings this highly advanced and exciting game to life. Developed with advanced artificial intelligence, Bridge Deluxe 2 with Omar Sharif includes all the intricacies of rubber bridge and is displayed in stunningly beautiful SVGA graphics. An in-depth tutorial with full-motion video and digitized speech of Omar Sharif will teach the beginning player the various strategies of bridge and will challenge the advanced player to championship level.' FROM games WHERE igdb_id = 85921 ON CONFLICT (game_id, language_code) DO NOTHING;
