INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Don''t Know Jack: The NetShow', 'You Don''t Know Jack: The NetShow was a free-to-play online trivia game based on the You Don''t Know Jack series, where you and three other players in the same keyboard could play different episodes that were released weekly and had short television-like full-screen commercials ads in between rounds. The game shut down some time around early 2001.' FROM games WHERE igdb_id = 391588 ON CONFLICT (game_id, language_code) DO NOTHING;
