INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Great Cave Offensive', 'The Great Cave Offensive is the fourth main game available in Kirby Super Star and its remake, Kirby Super Star Ultra. It features a large labyrinthine cavern system divided into four stages, with the goal being to escape the cave, while collecting Treasure along the way.' FROM games WHERE igdb_id = 271262 ON CONFLICT (game_id, language_code) DO NOTHING;
