INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('silent-hunter', 15517, '1996-02-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/qtfhhgpv5dzicqpuhxxq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf5ru.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Hunter', 'Silent Hunter is a World War II U.S. Fleet Submarine Combat Simulator. As a commander of a U.S. submarine in the Pacific Theatre, from Pearl Harbor to the end of the war, you have a variety of submarines from which to choose and your task is simple, sink as much enemy tonnage as possible. One can play historical missions, hypothetical encounters or the career based campaign game. There are 9 patrol zones,from the Solomons to the Sea of Japan, and many coastal cities, ports and harbors to sneak into on either recon missions or to just sink ships tied up in port. As commander you may receive medals or commendations after especially successful or hazardous missions. Compare your tonnage and kill scores to those of actual commanders of the period and see if you can match up to the best.' FROM games WHERE igdb_id = 15517 ON CONFLICT (game_id, language_code) DO NOTHING;
