INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BS Super Mario USA: Power Challenge', 'BS Super Mario USA is a direct sequel to Super Mario Bros. 2 for the Satellaview, an add-on for the Super Famicom. It was the first Mario platformer game to make use of the Satellaview''s Soundlink features. The gameplay and levels are essentially the same as the SNES version of Super Mario Bros. 2, but with numerous added features and a new plot, presented as a sequel to the original game. Dramas by voice actors are also featured, the cast is: Toru Furuya as Mario, Mariko Mukai as Peach / Princess Toadstool, Ichirota Miyakawa as Luigi, Nanae Sumitomo as Kinopio / Toad, and "Mr. Lady" as Catherine / Birdo.' FROM games WHERE igdb_id = 67027 ON CONFLICT (game_id, language_code) DO NOTHING;
