INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'G.O.D: Mezame yo to Yobu Koe ga Kikoe', 'is a console-style RPG with randomly encountered enemies whom you fight in turn-based combat viewed from “over-the-shoulder” perspective, similar to Phantasy Star IV. Gen and other party members develop special powers called “chakra”, which can be leveled up just like the characters themselves.' FROM games WHERE igdb_id = 42433 ON CONFLICT (game_id, language_code) DO NOTHING;
