INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('age-of-sail', 9430, '1996-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/g8gcvhljiz8c2h5s7urk.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Sail', 'Explosive real-time naval combat. Time 1775 to 1820- All the grandeur and pageantry of the Tall Ships era along with some bone-crunching, wood-splintering cannon shots to liven things up! Talonsoft, creators of the award-winning Battleground series, is proud to introduce its new real-time historical strategy series! Age of Sail delivers an excellent blend of exciting real-time naval combat and vivid 3-D graphics. Take command of the greatest sailing ships in history! Ships include the Victory, Constitution, Constellation, Bonhomme Richard, Espanol, Guerriere, Vengeance, and Saratoga just to name a few! Complete Campaign Game (1775 to 1820). Can you rise from a lowly Ensign to Admiral of the Navy? Enlist in the navy of Britain, Spain, France or the United States! 100 Scenarios including the battles of Trafalgar, Camperdown and Cape St. Vincent! Complete Scenario Editor, with over 2,000 historically accurate ships representing all major and minor countries, lets you create instant naval combat to your specifications.' FROM games WHERE igdb_id = 9430 ON CONFLICT (game_id, language_code) DO NOTHING;
