INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('christmas-nights-into-dreams', 45501, '1996-11-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6f93.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uthdzcdg06zxdtrf9fj5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Christmas Nights into Dreams', 'The story of Christmas Nights follows Elliot and Claris during the holiday season following their adventures with Nights. Though they both enjoy the Christmas season, they feel as if something is missing. Finding that the Christmas Star that usually sits at the top of the Twin Seeds Christmas tree is missing, the pair head off to Nightopia to find it. There, they meet up with Nights again and re-explore Spring Valley, which has now been Christmas-ified due to the kids'' dreams of the holiday season. The trio of heroes must now take down a revived Gillwing and retrieve the Christmas Star from his lair. The game uses the Saturn''s internal clock to change elements of the game according to the date and time. In November and January, the title screen label "Nights: Limited Edition" is changed to "Winter Nights", with the lush greenery of the environment being replaced by white snow. During December, "Christmas Nights" mode is activated, resulting in further Christmas-themed alterations, such as item boxes becoming Christmas presents, Nightopians dressing in elf costumes, and Christmas trees replacing Ideya captures. The background music is replaced by an instrumental version of "Jingle Bells", as well as there being a "Christmas-like" rendition of the boss theme. During the "Winter Nights" period, the weather in Spring Valley will change according to what hour it is. Other cosmetic changes are visible on New Year''s Day, and loading the game on April Fool''s Day results in Reala replacing Nights as the playable character.' FROM games WHERE igdb_id = 45501 ON CONFLICT (game_id, language_code) DO NOTHING;
