INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Puyo Puyo Tsuu Remix', 'Super Puyo Puyo 2 Remix is a puzzle action game released by Compile for the Super Famicom. The mayor differences between this "Remix" version and regular Super Puyo Puyo 2 is that you now can play 4 player multiplayer with bots. An Expert course is added to the game and other small minute changes.' FROM games WHERE igdb_id = 42544 ON CONFLICT (game_id, language_code) DO NOTHING;
