INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JetPilot', 'JetPilot features the Lockheed F-104 and the English Electric Lightning. Take to the skies in this incredibly realistic 3d flight simulator, whether you are a novice pilot or an experienced enthusiast this title will satisfy your craving for reality. The control methods are as simple or as complicated as you like, either way they perform within 10% of the real thing. As well as practice and situation flying you will also be required to successfully complete some 20 qualification missions where a high level of concentration and situation awareness is required to successfully intercept targets from Scotland to the Mediterranean.' FROM games WHERE igdb_id = 93138 ON CONFLICT (game_id, language_code) DO NOTHING;
