INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Make Believe Treasure Isle', 'More make believe fun and learning is here from the publishers of My Make Believe Castle. Bursting with never-ending creative play, My Make Believe Treasure Isle uses the power of a child''s imagination to propel learning adventures on a treasure island. Problem solving and logical reasoning skills are reinforced through a series of challenging activities. "At last, software where the child programs the computer and not the reverse... a software toy that puts children''s imagination in charge". Dr. Seymour Papert MIT Media Lab Cambridge, MA' FROM games WHERE igdb_id = 329471 ON CONFLICT (game_id, language_code) DO NOTHING;
