INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sea Legends', 'The year is 1667, and the sea is a dangerous place. In this picturesque game combining role-playing adventure, fleet-building strategy, swashbuckling action, and naval combat, you''ll need keen planning and swordsmanship to reach the story''s end – or turn pirate to lead your fleet to infamy.' FROM games WHERE igdb_id = 146227 ON CONFLICT (game_id, language_code) DO NOTHING;
