INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('american-oudan-ultra-quiz', 305026, '1996-02-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8qp2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsnv5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'American Oudan Ultra Quiz', 'America Ōdan Ultra Quiz is based on the Japanese TV show of the game name. Like the original show, the game focuses on trivia questions solely related to the United States of America. Areas of knowledge include history, geography, culture, literature, sports, language, and others. The main quiz show takes place in New York and involves questions in random categories. A special travel mode allows the player to visit various locations in the USA, including notable airports, beaches, sports stadiums, and other popular travel destinations. Each of these locations has its own challenges in additional to the trivia questions. For example, in Las Vegas the player''s answers are further configured by a slot machine, in Santa Fe the player is prompted to run a certain distance by rapidly pressing keys, etc.' FROM games WHERE igdb_id = 305026 ON CONFLICT (game_id, language_code) DO NOTHING;
