INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SD Gundam Generation: Babylonia Kenkoku Senki', 'A strategy game based on the Second Neo-Zeon War from Char''s Counterattack and the Cosmo Babylonia War from Gundam F91. It uses the Sufami Turbo accessory to connect to other SD Gundam Generation games.' FROM games WHERE igdb_id = 66476 ON CONFLICT (game_id, language_code) DO NOTHING;
