INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('suiko-enbu-fuunsaiki', 94450, '1996-03-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ork.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Suiko Enbu Fuunsaiki', 'An enhanced port of Suiko Enbu (aka, Dark Legend) exclusively upgraded for the Saturn. The game is a one-on-one 2D fighting set in medieval China and based around the myths of the classic "Shuihuzhuan" Chinese story. As usual for a beat ''em up, gameplay consists of you selecting your champion from a group of 14 fighters and clashing against each other using your specific moves and attacks. Additionally, each character fights with his own unique weapon, but depending on how much you block your weapon can break and you must finish the fight barehanded and using a different moveset and generally faster (but less powerful) attacks. This enhanced port features three additional speed settings and refined balance between each fighter, two all new characters (plus the main boss as a selectable fighter) a brand new intro and new backgrounds. Features single-player or two-player vs gameplay.' FROM games WHERE igdb_id = 94450 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 94450 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
