INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snood', 6596, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6sar.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5tjg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snood', 'If Snood is new to you, then you probably don''t download much shareware from the Internet. The color-matching puzzle game has been a mainstay on PCs for several years. It may remind you a little of Bust-a-Move, but its simplified game play and colorful characters add a new dimension to the fun. Fire colorful, little Snoods into each other so they cling together and then fall from the lineup.' FROM games WHERE igdb_id = 6596 ON CONFLICT (game_id, language_code) DO NOTHING;
