INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('die-fugger-ii', 85791, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2px4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc104lo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Die Fugger II', 'Germany in the year 1600 - the empire of the Fuggers is destroyed. Now it''s your turn to rise it again. "Die Fugger 2" is a turn based trading simulation. During the game you can expand your business over 16 towns and try to become emperor of the country. Trading is the way you''ll get your money. But it''s not that easy, your trails may be plundered, your stocks may burn down, or anything else. It''s also possible to get your own pirate hideouts to plunder your competitors goods. But be careful, if they find out who did that, you may end up in prison. When you claim a higher political position it''s possible for you to change laws, rise taxes and much more.' FROM games WHERE igdb_id = 85791 ON CONFLICT (game_id, language_code) DO NOTHING;
