INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sampras-extreme-tennis', 44851, '1996-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobd4z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar566a.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sampras Extreme Tennis', 'The introduction in the manual says: "Welcom to Sampras Extreme. The ultimate tennis simulation featuring the ultimate tennis player. The most realistic, and exciting tennis simulation awaits you and your friends. Play single matches of your choice in exotic locations around the world. See the spectacular stadiums, sample the local native language and view the breathtaking 3 D action. Meet the game´s characters and find out what makes one tick. Monster serves, ´baseline´ tactics, ´rush to the net´ tactics, you´ll have to cope with them all. Plunge yourself into the Sampras Extreme World Tour and see how high in the rankings you can reach. You´ll have to adopt extreme tactics of your own if you´re going to come face to face with The World Number One - Pete Sampras, let alone beat him. even then, there is more to come...' FROM games WHERE igdb_id = 44851 ON CONFLICT (game_id, language_code) DO NOTHING;
