INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jungle Park', 'Jungle Park is a point and click adventure game that invites the player to explore the titular park. More a walking simulator than a traditional adventure game, it has few goals and instead lets the player discover the park and its surroundings at their own pace. Inspired by an amusement park bearing the same name, Jungle Park incorporates elements of a role-playing game with a picture gallery and animation.' FROM games WHERE igdb_id = 92107 ON CONFLICT (game_id, language_code) DO NOTHING;
