INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raiden Fighters', 'Choose from among seven high-powered fighters (including the Raiden MkII and Judge Spear from Viper Phase 1) and take to the skies in three dangerous missions. The first two missions are comprised of three stages each, the first two of which may appear in either order. Stage 1-3, Stage 2-3, and the final mission are all the same.' FROM games WHERE igdb_id = 8858 ON CONFLICT (game_id, language_code) DO NOTHING;
