INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tenchi Muyo! Mimiri Onsen: Yukemuri no Tabi', 'Tenchi Muyō! Mimiri Onsen: Yukemuri no Tabi is an adventure game based on the Tenchi Muyo anime series. The game is fully-voiced, not including even a dialogue display or subtitles, and progresses as is standard for Japanese adventure games. In each scene, the player can inspect various parts of the scene, move between locations, and talk to each of Tenchi''s companions, with the story generally progressing after all relevant options have been exhausted. There are ten different endings depending on the player''s choices and who they decide to talk to.' FROM games WHERE igdb_id = 289363 ON CONFLICT (game_id, language_code) DO NOTHING;
