INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Rally Fever: Born on the Road', 'World Rally Fever is a thrilling, no-nonsense arcade style game. Features include a hyper-fast 3D and sprite engine, incredible screen rotation and camera panning, a host of cool anime-style characters to select from, sixteen taxing stages set in ten exciting locations and stunning CD Audio music throughout.' FROM games WHERE igdb_id = 8494 ON CONFLICT (game_id, language_code) DO NOTHING;
