INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart Toddlers', 'JumpStart Toddlers is a game released by Knowledge Adventure in 1996 that focuses on educational concepts for toddlers. It would later be replaced by JumpStart Toddlers (2000). It is also known as Jump Ahead Toddlers in Europe. The player''s guide and mascot for the game is Giggles the gopher. In the game, the player can click on many different items in a playroom and play seven different activities. During an activity, the player can use the Button Bar at the bottom of the screen to access the other activities or return to the playroom.' FROM games WHERE igdb_id = 129111 ON CONFLICT (game_id, language_code) DO NOTHING;
