INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mohawk-and-headphone-jack', 42487, '1996-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5z3i.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mohawk & Headphone Jack', 'Protean platform hero with attitude (well, with sunglasses) rocks out in this novel but forgotten would-be Sonic-killer, collecting CDs (this is pre-Napster, remember) and avoiding segmented slinkies and nasty robot bugs in disorienting mode 7 mazes with no constant "down". The boneless wonder (er, and his Walkman) pours himself into cracks, splatters against walls, curls into a defensive porcupine-koosh hybrid, always lands on his feet (by growing feet where his hands were!) and blasts apart into little jelly gibs as a special offensive attack. Gross. And as if a radical surferpunk made of snot wasn''t cool enough to begin with, a power-up gives him a chopper wheel in place of feet. Dude is the hood ornament on his own motorbike! One- or two-player (nonsimultaneous).' FROM games WHERE igdb_id = 42487 ON CONFLICT (game_id, language_code) DO NOTHING;
