INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jikkyou Oshaberi Parodius: Forever With Me', 'Released a year after Jikkyou Oshaberi Parodius, this port for the Sega Saturn and PlayStation includes improved graphics and sound over the Super Famicom release. Additional features include a cheat to replace "Tokimeki People''s Dance" with an enhanced version, "Days Of The Dream''s Memories", several "Omake" stages, and unlockable characters Dracula-kun and Kid Dracula. The two-player game also allows both players to play simultaneously instead of just alternately like in the Super Famicom game.' FROM games WHERE igdb_id = 45458 ON CONFLICT (game_id, language_code) DO NOTHING;
