INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fennels Figure Math', 'The Fennels Figure Math is an educational adventure game with a quirky and surreal setting. You play as Baxter, who, alongside his lazy cousin Frizzie, must collect five food items for a party in their eccentric Great-Great-Great Grandfather''s bizarre house. From ice sculptures in the North Pole Room to alien-infested trailers, you''ll solve math-based puzzles to progress. The game combines whimsical storytelling with educational challenges, making math fun and engaging.' FROM games WHERE igdb_id = 93189 ON CONFLICT (game_id, language_code) DO NOTHING;
