INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('arthur-to-astaroth-no-nazomakaimura-incredible-toons', 45427, '1996-08-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co95y9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar34vk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arthur to Astaroth no Nazomakaimura: Incredible Toons', 'A Japanese-only entry in Dynamix''s The Incredible Machine series based on the Ghosts ''N Goblins series. It is the only The Incredible Machine game with a plot, which is the same as in every Ghosts ''N Goblins game: the princess is kidnapped by Astaroth (the main villain of the games), so Arthur (the main character in the series) has to save her. It features all of the known characters of the series, such as the Red Arremer (who would get his own game series: Gargoyle''s Quest). It also features items from the game, for example the armor icon, which is required for Arthur to move in this game. Not only does it have the most well known characters in the Ghosts ''N Goblins games, it also features remixed music of the series. As with the The Incredible Machine games, there are different kinds of puzzles, one of them even involves killing Arthur. However, unlike the The Incredible Machine games, there are no Head-to-Head puzzles and no Freeform Machine mode, so there''s only single player puzzles.' FROM games WHERE igdb_id = 45427 ON CONFLICT (game_id, language_code) DO NOTHING;
