INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Waku-waku Ultraman Racing', 'Waku Waku Ultraman Racing is a Kiddie Ride and Arcade Game based on the Ultraman Series. Riders sit on Ultraman, and control Ultraman or Ultraseven as they race against several Kaijus and Alien Baltan. At some point during the race, the riders will have to fight Baltan to win the race. The ride ends when the riders reach the goal.' FROM games WHERE igdb_id = 252170 ON CONFLICT (game_id, language_code) DO NOTHING;
