INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lunar-sanposuru-gakuen', 46354, '1996-02-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zeb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uyqr19fijggjkvsnmle5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar: Sanposuru Gakuen', 'This is a side-story, set in the same world as the famous Lunar RPGs: Silver Star and Eternal Blue. The town of Burg is populated by harvesters, and you take control of two girls, Ellie and Lena. One day, they are sent to the island of Ien where they should study magic, and there begins their adventure. The game is a traditional Japanese-style RPG. You navigate your party through a top-down world, visiting towns and hostile areas. Enemy encounters are random, the battles are turn-based and are viewed from first-person perspective. Whilst not officially released in English, there is now a completed fan-translation of this game.' FROM games WHERE igdb_id = 46354 ON CONFLICT (game_id, language_code) DO NOTHING;
