INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gateway to English: Eigo de Go!', 'This game is designed to teach Japanese how to speak English through four different activities. Those activities include: Typing on an English or Japanese Katakana tutor keyboard to learn words and the objects that pair with them. Four different domestic locations with objects and their names dictated. Four categories of puzzles that indicate objects and their relationships. Four radios with their own topic, which show an object, the name in English and the name in Japanese.' FROM games WHERE igdb_id = 245313 ON CONFLICT (game_id, language_code) DO NOTHING;
