INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gender-wars', 50141, '1996-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6wur.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3woi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gender Wars', 'Gender Wars is a real-time tactics action game for DOS developed by The 8th Day and published by GT Interactive Software and Sales Curve in 1996. After eons of fighting between the genders, men and women have broken into separate factions, each using genetic engineering to create new followers, and waging terrible war upon each other. Upon selecting the side you wish to play (depicted as either clueless blondes who can''t drive, or beer-swigging lazy oafs), you select a team of 4 for your missions, arm them up with guns and other assorted weaponry, and wreak havoc on the ''enemy'' in this isometric Syndicate-like game. Progress through the levels to the final conflict, collecting tanks and other assorted ''powerups'' along the way, and watching the humourous cutscenes as you go.' FROM games WHERE igdb_id = 50141 ON CONFLICT (game_id, language_code) DO NOTHING;
