INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kurayami', 'Kurayami (meaning "darkness") is a visual novel concentrating on dialogue and decision-making within the confined setting of a broken elevator and developing relationship between the hero and the young woman. Depending on the player''s choices, their relationship will evolve in different ways, leading to different endings. The game contains scenes with nudity and sexual situations.' FROM games WHERE igdb_id = 187054 ON CONFLICT (game_id, language_code) DO NOTHING;
