INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('madeline-european-adventures', 210114, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8kw4.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madeline: European Adventures', 'Children join author Ludwig Bemelmans'' brave little Parisian schoolgirl as she and her eleven roommates travel the continent, in Madeline European Adventures. This educational game, intended for children ages five and up, is designed to help players develop critical thinking and problem-solving skills, as well as an awareness of foreign languages. As they travel with Madeline from Paris to Switzerland, Italy, and Turkey, players will help the girls solve four main mysteries -- one in each country. Children can also become familiar with the locations, capitals, and flags of 19 European nations, and the game encourages players to learn over 100 words in Spanish and French.' FROM games WHERE igdb_id = 210114 ON CONFLICT (game_id, language_code) DO NOTHING;
