INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leo the Lion', 'Discover this classic action-adventure game from Poland and join Leo the Lion on his adventures full of unexpected situations, challenges, and brawls. Travel the islands of Lion’s Archipelago and help him find the stolen crown. Try to survive in the jungle, pole, in the dungeons of the magic castle, inside pyramids and on the burnt deserts. Examine the wrecks of pirate ships on the bottom of the sea, and survive the eruption of the volcano. Experience crazy adventures and rack your brains to save Leo from traps and troubles.' FROM games WHERE igdb_id = 124823 ON CONFLICT (game_id, language_code) DO NOTHING;
