INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Andretti Racing', 'For the first time ever in an arcade racer, take control of either NASCAR or Indy cars and cruise around 16 detailed tracks. There are 3 views available to drive from. As well as individual races, you can play a full career. Derek Daly and Bob Jenkins provide a running commentary. Outside factors such as pit-crew mistakes and mechanical failures can affect your races.' FROM games WHERE igdb_id = 45496 ON CONFLICT (game_id, language_code) DO NOTHING;
