INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lupin III: The Master File', 'Lupin III: The Master File is a collection of materials related to the production of the Lupin III anime from 1971 to 1994. This includes character sheets, location maps, original sketches, music, poster scans, and plot summaries. An expanded edition of Master File was released on DVD and Blu-Ray on March 28, 2012.' FROM games WHERE igdb_id = 66213 ON CONFLICT (game_id, language_code) DO NOTHING;
