INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chip-chan Kick!', 'This is a platform game similar in style to Bubble Bobble and particularly to Parasol Stars. There are two playable characters, both of which are little girls. There is no difference between them gameplay-wise: both use a large blob-like animal to hit enemies from a short distance in a yo-yo-like fashion. It is possible to choose one of them as a single player, or to use them both cooperatively in the two-player mode.' FROM games WHERE igdb_id = 45961 ON CONFLICT (game_id, language_code) DO NOTHING;
