INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Living Books: Stellaluna', 'Stellaluna is a Living Book adaptation based on Jannell Cannon’s original picture book. The story is about a bat named Stellaluna, who lost her mother due to an owl crashing into her. Stellaluna has to find her mother, but she meets new friends throughout the story. There is also a Bat Quiz in which children test their knowledge of Bats. In Let Me Play, every page can be clicked to uncover a surprise or two.' FROM games WHERE igdb_id = 229068 ON CONFLICT (game_id, language_code) DO NOTHING;
