INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spectral Tower', 'Spectral Tower is the first game in the RPG series released by Idea Factory for the Playstation One console, the game begins with an intro in which the adventurer arrive to a big tower that is located in an isolated desert. The gameplay is in third person perspective using an overview view meanwhile the player is exploring the different floors of each tower, and in a first person perpective for the battle parts.' FROM games WHERE igdb_id = 281680 ON CONFLICT (game_id, language_code) DO NOTHING;
