INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gakkou de Atta Kowai Hanashi S', 'Gakkou Deatta Kowai Hanashi S is a survival horror visual novel, developed by Pandora Box and published by Banpresto, which was released in Japan in 1996 and is the PlayStation version of that SNES game featuring enhanced graphics and sounds and new FMV sequences. The game features pictures of real Japanese actors/models, and CAMERA J. The game is a compilation of about 50 scary stories which is played in the setting of a school. The graphics bring up a feeling of fear by using on-the-spot photography. Since it uses multi-stories, you can enjoy those stories any number of times.' FROM games WHERE igdb_id = 112565 ON CONFLICT (game_id, language_code) DO NOTHING;
