INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lu-ye-xian-zong', 320152, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ydv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scu88f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lu Ye Xian Zong', 'A platformer in which the player has to guide the characters from the film with each of them having their own abilities. The plot follows that of the 1939 movie. Many of the graphics are ripped from numerous other games. The title screen bears a strong resemblance to Castle of Dragon''s intro. Barza from Kyoryu Sentai Zyuranger is used in the cutscenes, the "To Green Castle" signs are taken from Mickey Mousecapade, the "Good luck!" message in the opening story being taken from Crossfire, the windows in the first level are likely re-edits of those from Hummer Team''s Aladdin pirate, and Willy from Rockin'' Kats shows up several times in the ending sequence. As well as this, the mushroom enemy is taken from Don Doko Don 2 and the small one-eyed green blobs that the frog spits at you are the aliens from one of the bosses in Chip ''n Dale Rescue Rangers for NES, while one more enemy is from Little Samson. A few enemies are taken from Panic Restaurant, such as the jumping sausage (re-colored to green). The last boss is copied from Chip ''n Dale Rescue Rangers 2 being re-drawn in other colors and with new attacks. The music is original, but the sound engine is stolen from Konami. Many of the sound effects also come from Konami games, most notably the death sound being the same as the one in Contra.' FROM games WHERE igdb_id = 320152 ON CONFLICT (game_id, language_code) DO NOTHING;
