INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('akazukin-cha-cha', 15887, '1996-08-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4weq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hs7mkq4kyircxy9jls3v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akazukin Cha-cha', 'Akazukin Cha-cha is the story of a young magical girl named Chacha. She lives in a cottage on Mochi-mochi Mountain with Seravy, her guardian and teacher, who is the fictional world''s greatest magician. Chacha is clumsy in casting her spells, frequently mistaking homonyms, she summons spiders (kumo (蜘蛛?) in Japanese) instead of a cloud (also kumo (雲?)). When she and her friends are in trouble, however, her spells do work. Living on the same mountain is a boy named Riiya, gifted with enormous strength, who comes from a family of werewolves. Far away from Mochi-mochi Mountain is Urizuri Mountain where Dorothy, a well known magician, lives in a castle with her student Shiine. Shiine is a young wizard, who is adept at casting spells and barriers, as well as transformations.' FROM games WHERE igdb_id = 15887 ON CONFLICT (game_id, language_code) DO NOTHING;
