INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yaku: Yuujou Dangi', '"Yaku - Yuujou Dangi is a first person perspective adventure game in which the player controls a young kid and his friend (a young girl) that decide to enter a mysterious mansion one night, and as soon as they arrive there they become separated and start to go around the mansion and strange things and horrible creatures appears. The player controls both characters at the beginning of the game (and the adventure of each character will advance in a way or another depending of the player choices) the boy is the first option to choose in the main menu of the adventure and the girl the second option.' FROM games WHERE igdb_id = 124642 ON CONFLICT (game_id, language_code) DO NOTHING;
