INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RedCat: De Woeste Woordenbrij', 'Brutus stole the letters from RedCat during a spaceflight. In a chase by RedCat, Brutus crashes into a desert planet and RedCat scans the surface to find the letters again. Brutus, along with Max, works against him quite a bit in his attempts to collect the letters.' FROM games WHERE igdb_id = 201300 ON CONFLICT (game_id, language_code) DO NOTHING;
