INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobile Suit Gundam Version 2.0', 'Mobile Suit Gundam 2.0 is an upgraded do-over of the previous PlayStation game based on the original anime''s storyline, Mobile Suit Gundam. This version retains the same storyline, first-person cockpit perspective, and control scheme, but has upgraded the experience across the board. 3D objects now appear in stages, which are newly designed.' FROM games WHERE igdb_id = 159155 ON CONFLICT (game_id, language_code) DO NOTHING;
