INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SPQR: The Empire''s Darkest Hour', 'SPQR is a 3D adventure game that challenges you to learn how the Roman Empire works - structurally, mechanically, economically, culturally and politically. Players are given one year to investigate five equally suspicious suspects in order to solve the ultimate mystery: Who is plotting to destroy Rome and how will they do it?' FROM games WHERE igdb_id = 73328 ON CONFLICT (game_id, language_code) DO NOTHING;
