INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lucky-luke--2', 134833, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5pkv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8bt7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucky Luke', 'The most infamous outlaws in the old west have broken out of jail, and Lucky Luke is the only cowboy crazy enough to try to stop them. Facing the likes of Billy the Kid, Jesse James and the Dalton brothers, it''s up to you to guide Lucky Luke - the rootin'', tootin'' star of comic books, TV shows and movies - through 12 levels of platform-jumping action across the south-western states of historic America. French development company Infogrames has packed Lucky Luke with a fascinating mix of gameplay elements, forcing Lucky Luke to survive tornados, stagecoach rides, train chases and buffalo stampedes. Clear, colourful graphics bring the old west landscape to sparkling life, with a ramblin'' soundtrack that''s sure to get your spurs tapping. Chasing bank robbers is as fun as it looks on TV, and thanks to solid play control and plenty of variety in the gameplay - including a heap of bonus games like the Shooting Gallery - you''re sure to have a wild, wild time in the old west.' FROM games WHERE igdb_id = 134833 ON CONFLICT (game_id, language_code) DO NOTHING;
