INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BS Marvelous: Time Athletic', 'BS Marvelous: Time Athletic is a Downloadable 4-part Soundlink game for the Satellaview that ran between January 1, 1996 and January 31, 1996. The game was broadcast in as a rerun in April, 1996. A sequel to BS Marvelous: Time Athletics entitled BS Marvelous: Camp Arnold was released in November, 1996 as a direct prequel to Marvelous: Mouhitotsu no Takarajima which was not broadcast via Satellaview but instead released in hard copy as a SFC cartridge.' FROM games WHERE igdb_id = 134432 ON CONFLICT (game_id, language_code) DO NOTHING;
