INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dig Dug Arrangement', 'Dig Dug Arrangement is, as the name suggests, a remake of Namco''s 1982 arcade game Dig Dug; it was released in 1996, as a part of the compilation arcade game, Namco Classics Collection Vol. 2, and later rereleased alongside the original and ten others in the Nintendo GameCube, PlayStation 2 and Xbox versions of Namco Museum in 2002.' FROM games WHERE igdb_id = 132160 ON CONFLICT (game_id, language_code) DO NOTHING;
