INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starwinder: The Ultimate Space Race', 'In Starwinder: The Ultimate Space Race, you assume the role of Conner Rhodes, the first representative of Earth sent to compete in a galaxy-wide race. This isn''t an ordinary race, however -- an unknown alien race built magnificent rails/tracks throughout the confines of space. Spanning thousands of miles in length, rails act in such a way that when pilots navigate toward one, it increases the speed of the ship.' FROM games WHERE igdb_id = 72069 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 72069 AND p.igdb_id = 7 ON CONFLICT DO NOTHING;
