INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kirby-no-omochabako-pinball', 134452, '1996-02-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30d3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scabxu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby no Omochabako: Pinball', 'This game is a simple game of pinball, where the player has to launch Kirby into the enemies on the stage to earn points. The hero first has to be shot out of a cannon at whatever power level the player chooses. If Kirby falls down the drain three times, the game ends. As with Kirby''s Toy Box - Baseball, the game could be played over and over during the brief period it was broadcast, but could not be played after that time, unless it had already been saved onto. Enemies in this game include King Dedede, Mr. Frosty, Kracko, Co-Kracko, Bounder, Waddle Dee, Crack-Tweet, and Elieel. Like every other sub-game in Kirby''s Toy Box, this game could only be downloaded by the Satellaview during the brief period it was broadcast.' FROM games WHERE igdb_id = 134452 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 134452 AND ge.slug = 'pinball' ON CONFLICT DO NOTHING;
