INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kirby-no-omochabako-guru-guru-ball', 134453, '1996-02-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30d4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8aqy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby no Omochabako: Guru-guru Ball', 'In this game, the player fires spherical Kirbys through a spiral tube, which is designed to look like Efreeti. This tube has holes in it, which a speedy Kirby will pass right over. The point is to fire the Kirbys with just the right amount of power to pass over certain holes but slow down and fall into another hole. Different holes give different numbers of points, so the goal of the player is to shoot his/her Kirbys into the highest-scoring hole as much as possible. When the player runs out of Kirbys, the game ends. Like every other sub-game in Kirby''s Toy Box, this game could only be downloaded by the Satellaview during the brief period it was broadcast.' FROM games WHERE igdb_id = 134453 ON CONFLICT (game_id, language_code) DO NOTHING;
