INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kirby-no-omochabako-pachinko', 134456, '1996-02-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30d9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ar1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby no Omochabako: Pachinko', 'This game is like a pachinko machine; the goal is to launch the spherical Kirbys the player is given into the pockets of the machine. The player is given two minutes to fire an unlimited number of Kirbys, and he/she is given control of the power put into each shot. Ten points are awarded whenever a Kirby lands in a pocket. If a shot lands directly atop the big Kirby in the center, the player will temporarily win a chance to earn more points; the big Kirby will raise his arms and give 100 points to each shot that hits him in one of three locations. When time is up, the game ends. Like every other sub-game in Kirby''s Toy Box, this game could only be downloaded by the Satellaview during the brief period it was broadcast.' FROM games WHERE igdb_id = 134456 ON CONFLICT (game_id, language_code) DO NOTHING;
