INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Expert', 'Uncover the truth of the incident that struck the intelligent building that has been occupied by the terrorists as a member of the "Expert" Special Forces! 3D gun shooting game that captures the action in a first person perspective. Explore the building freely, but be careful and take out the enemy before they take you out!' FROM games WHERE igdb_id = 43796 ON CONFLICT (game_id, language_code) DO NOTHING;
