INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Master''s: Haou Ninpou-ko', 'Ninja Master''s follows the conventions of many previous 2D fighting games released for the Neo-Geo. The player must defeat their opponent in combat in a series of best-two-out-of-three matches. Characters can change between using the character''s weapon or fight hand-to-hand during the middle of combat. Like the Art of Fighting series, Ninja Master''s features a super meter.' FROM games WHERE igdb_id = 39458 ON CONFLICT (game_id, language_code) DO NOTHING;
