INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kizuna Encounter: Super Tag Battle', 'Kizuna Encounter: Super Tag Battle is a fast tag‑team fighting game that swaps Savage Reign’s two‑plane system for dynamic tag combat, emphasizing team synergy, chain combos, and simplified controls for more fluid, strategic matches. Players pick two fighters, use tag cancels and partner assists to extend combos and shift momentum in high‑risk 2D arcade battles. The roster is largely retained with Nicola and Carol replaced by Rosa and Kim Sue Il. A new final boss, Jyazu, blends moves from Gozu and Mezu, adding extra challenge.' FROM games WHERE igdb_id = 39530 ON CONFLICT (game_id, language_code) DO NOTHING;
