INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bishoujo Senshi Sailor Moon Sailor Stars: Fuwa-fuwa Panic 2', 'Bishoujo Senshi Sailor Moon Sailor Stars: Fuwa-fuwa Panic 2 is a video game released exclusively in Japan by Bandai on September 27, 1996. the Super Famicom and is the sequel to Sailor Moon SuperS: Fuwa Fuwa Panic. The game made use of Bandai''s SuFami Turbo accessory and could not be played without it.' FROM games WHERE igdb_id = 56370 ON CONFLICT (game_id, language_code) DO NOTHING;
