INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Kirby', 'Samurai Kirby is a sub-game of Kirby Super Star. This sub-game was also ported and released as a trial version for the Satellaview as part of the Kirby no Omochabako (Kirby''s Toy Box) series of standalone minigames. No footage or file of this version has since been found.' FROM games WHERE igdb_id = 134459 ON CONFLICT (game_id, language_code) DO NOTHING;
