INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Math Blaster Jr.', 'The game sees the Blaster Pal characters head to the Plusto galaxy in outer space to solve math problems. By solving addition and subtraction problems, they earn printable certificates. The game contains several activities, puzzles, and songs. The game is intended to encourage "math readiness"' FROM games WHERE igdb_id = 129397 ON CONFLICT (game_id, language_code) DO NOTHING;
