INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pray for Death', 'Through time and space he finest warriors in creation have gathered together for the ultimate showdown. At the behest of Death himself, angel will fight demon, wizard will fight warlord, robot will fight human. The creature that triumphs in this awesome battle will be rewarded with that most precious of commodities - life itself.' FROM games WHERE igdb_id = 47104 ON CONFLICT (game_id, language_code) DO NOTHING;
