INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spring Breeze', 'Spring Breeze is the first main game in Kirby Super Star and Kirby Super Star Ultra. It is essentially a simplified remake of Kirby''s Dream Land, with some differences to compensate for this. It is the first main game to be playable, and is designed to introduce new players to the game.' FROM games WHERE igdb_id = 271258 ON CONFLICT (game_id, language_code) DO NOTHING;
