INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'J.B. Harold no Jikenbo: Kiss of Murder', 'Kiss of Murder is set in a parallel world to Manhattan Requiem, and while featuring the same set of characters as that title, has a completely different scenario. Early releases of the game were add-ons to "Manhattan Requiem" and used its graphical data. This version is a stand-alone release as a part of the Windows 95 Mystery Selection series.' FROM games WHERE igdb_id = 79622 ON CONFLICT (game_id, language_code) DO NOTHING;
