INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Ants', 'A multiplayer strategy game where you play as an army of ants making the best nest against other players. You win by gaining the most points which is done through eating and stealing food across maps. On January 31, 2006, Microsoft''s Zone retired Ants due to a lack of players.' FROM games WHERE igdb_id = 392624 ON CONFLICT (game_id, language_code) DO NOTHING;
