INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abmis the Lion', 'Abmis the Lion, King of the Beasts, has a problem: all of his kingdom''s potatoes have been stolen, without which his citizens may starve! You control his navigation through a side-view platform maze avoiding animal hazards and collecting dropped potatoes, using objects you find along the way, all in pursuit of the foxy thief. Once all a level''s potatoes have been collected, a magical door will open permitting access to the next level.' FROM games WHERE igdb_id = 70305 ON CONFLICT (game_id, language_code) DO NOTHING;
