INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pia Carrot he Youkoso!!', 'Yusuke Kinoshita is a 18-year-old male Japanese high-school student. He intends to have a cool summer vacation, but realizes he has no money. Having no choice, he takes a job in his father''s restaurant, "Pia Carrot". Thus begins an adventure much more exciting than the summer vacation he has dreamed about: he gets to know many beautiful girls in the restaurant, and has to decide which one is the love of his life...' FROM games WHERE igdb_id = 45955 ON CONFLICT (game_id, language_code) DO NOTHING;
