INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kakyuusei', 'Kakyuusei is a 1996 PC-98 adventure dating sim where the protagonist must date (obviously) a girl or two or a dozen. It was ported to many platforms and has never been localized into any other language besides Japanese officially (only fan translations into Korean and Simplified Chinese). It’s a spin-off of the Doukyuusei titles also made by ELF.' FROM games WHERE igdb_id = 153696 ON CONFLICT (game_id, language_code) DO NOTHING;
