INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ongaku Tsukuuru: Kanadeeru', 'Ongaku Tsukuuru: Kanadeeru is a Miscellaneous game, developed by Success and published by ASCII Entertainment, which was released in Japan in 1996. It is a Satellaview-compatible Slotted Cartridge game belonging to ASCII''s Tsukūru series. The title of these games are portmanteau-word puns mixing the Japanese word tsukuru (作る), which means "make" or "create", with tsūru (ツール), the Japanese transcription of the English word "tool". As the title suggests, this title is a music creation tool.' FROM games WHERE igdb_id = 44385 ON CONFLICT (game_id, language_code) DO NOTHING;
