INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokusou Kidoutai J-SWAT', 'Tokusō Kidōtai JSWAT is a police-themed, first-person shooter with live-action cutscenes and digitized graphics. For each mission, the player must select a weapon loadout and attempt to neutralize all threats. While lethal force is available as an option, subduing and arresting criminals is the preferred approach, and is reflected as such in mission rankings. The player must also be careful not to harm hostages and civilians, and pay attention to instructions received over radio during each mission.' FROM games WHERE igdb_id = 54732 ON CONFLICT (game_id, language_code) DO NOTHING;
