INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightruth: "Maria"', 'NIGHTRUTH: Explanation of the paranormal - "Maria" is a Sega Saturn visual novel developed by Sonnet Computer Entertainment and published by Varie. Released exclusively in Japan in December 1996, the game explores famous paranormal topics such as the Mary Celeste, and stars the titular protagonist from the earlier NIGHTRUTH: Explanation of the paranormal - #01 "Yami no Tobira", Maria. It was followed by a 1997 sequel NIGHTRUTH: Explanation of the paranormal - "Futatsu Dake no Shinjitsu".' FROM games WHERE igdb_id = 98288 ON CONFLICT (game_id, language_code) DO NOTHING;
