INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('power-rangers-zeo-full-tilt-battle-pinball', 43733, '1996-10-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ahn.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Rangers Zeo - Full Tilt Battle Pinball', 'Earth is under invasion by aliens and the only folks that can stop the madness are the TV heroes known as the Power Rangers. How are they going to do it? Pinball style! You''ll find all of the classic pinball bells and whistles here (ramps, spinners, bumpers, targets, flippers, and more), but the action is pure Power Rangers, taking place over five different 3D play fields. Not only that, the game boldly travels to 15 locations around the globe, including New York, Africa, and Japan. Between each level of play, you''ll see an awesome animated sequence that advances the storyline to its next phase. Based on what you see in the clips, you''ll have to accomplish certain missions in order to advance to the next stage. Though pinball has been around since the early part of the century, it''s never been so vast or explosive. The game''s makers even worked in such characters as Zeo Zords, King Mondo, and Queen Madrina, just to make things interesting. Whether you''re primarily a fan of the Power Rangers, pinball, or PlayStation games, you won''t be disappointed.' FROM games WHERE igdb_id = 43733 ON CONFLICT (game_id, language_code) DO NOTHING;
