INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Three Dirty Dwarves', 'Four genetically altered geeks have opened the trans-dimensional gates to reality and summoned a rag-tag posse of filthy orc dwarves to rescue them from their maniacal captor. Run amuch with up to 3 players, through over 20 hard-hitting whacko worlds of car-tooney ghettos and freaked-out bosses!' FROM games WHERE igdb_id = 45480 ON CONFLICT (game_id, language_code) DO NOTHING;
