INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('highway-2000', 46097, '1996-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co53ht.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scievs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Highway 2000', 'Rev up for the road race of the century! Highway 2000 delivers driving excitement with all cylinders firing! Fly through five harrowing highway courses with your choice of three high-performance racing machines - the speed and handling of the Mad Viper, the awesome acceleration of the Dark Nebula and the stick-to-the-road grip of the Rapid Fire. Slide with all four wheels into a hairpin curve. Negotiate treacherous tunnels, narrow bridges and heavy highway traffic. Challenge a fellow racer to a winner takes all split-screen barn burner! You can see the action from above, from the road or your driver''s seat. It''s your road! Get out onto the highway and go! This is the Australian/European version of Wangan Dead Heat, released in Japan. This version cut all of the content relating to wooing women in the career, a large part of the Japanese release. It is a spin-off of Genki''s Shutokou Battle racing series.' FROM games WHERE igdb_id = 46097 ON CONFLICT (game_id, language_code) DO NOTHING;
