INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sesame-street-get-set-to-learn', 70750, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co867c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvj5m.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sesame Street: Get Set to Learn', 'Kids learn thinking skills in Get Set to Learn! Thinking and problem solving skills provide a solid foundation for learning. Get Set To Learn! helps develop these abilities by introducing a wide variety of kindergarten readiness skills, then encouraging young minds to integrate these concepts to complete each activity. It''s the perfect preparation for a lifetime of learning! What Size is Your Prize?: Is it tall or short? Big or small? Pick the right prize size and win Zoe''s game! Count it Up! Up! Up!: Watch as the wheel spins to see which object comes up. Count and pick the right number to win! Match the Moons: The count has moons, spiders, lightning bolts, gold coins, and numbers. Can you match the number of things he has? Kooky Cookie Game: Cookie Monster has lots of yummy frosted cookies set up in a pattern. Complete the pattern to get a prize! Dunk or Dare: Fill the barrel with the right amount of yucky trash, and you get a chance to dunk Telly! Fabulous Prizes: Open up the chest and look at all of the wonderful prizes you''ve won!' FROM games WHERE igdb_id = 70750 ON CONFLICT (game_id, language_code) DO NOTHING;
