INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('punky-skunk', 44881, '1996-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yyu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8yxx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Punky Skunk', 'Punky Skunk is not your ordinary skunk: he''s an extreme-sports loving critter trying to save his friends from a kidnapping wolf named Badler. So begins this adventure of a hip skunk and his 30 levels of platforming action, taking him through the sky, across land, underneath the ground and over water. Multiple paths and bonus levels will offer some variety in this throwback to 2D platform games of the past. In order to succeed, Punky must use various moves to fight enemies, avoid traps and find the flagpole signifying the end of the level. In addition, you''ll be able to collect stars and 1-ups for extra lives, green orbs to replenish health, and gear icons outfitting Punky with one of six pieces of equipment: Paraglider, Inline Skates, Skysurfer, Pogo Stick, Jetpack or Diggers. Besides using the gear, Punky can either jump or attack enemies with his "spray." Skunk got you stumped? Not to worry, you can resume progress at the start of each cleared stage if you have a memory card.' FROM games WHERE igdb_id = 44881 ON CONFLICT (game_id, language_code) DO NOTHING;
