INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ds-diner-the-directors-cut', 245311, '1996-01-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co953i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuqo7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D''s Diner: The Director''s Cut', 'A director''s cut of D including additional cutscenes and trailers including the trailer for D2. The story begins in 1997. It''s the dead of night in the city of Los Angeles, and there has been a mass murder at a general hospital on the outskirts of downtown. The perpetrator is the director of the hospital, Richter Harris. He has shut himself up in the hospital and taken a number of patients as hostages, leaving the police helpless and unable to move in. Richter''s only daughter, Laura Harris, after hearing the situation, rushes to Los Angeles from San Francisco, and drives alone to the tragic scene at the hospital ground. Upon entering the hospital Laura finds herself transported to an old mansion, while the disembodied voice of her father pleads with her to leave. Nevertheless she must press forward to save her father and herself.' FROM games WHERE igdb_id = 245311 ON CONFLICT (game_id, language_code) DO NOTHING;
