INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shattered Steel', 'Save your species as you engage in fast-paced mechanized combat in the single-player campaign containing 50 adrenaline-pounding missions and arm your Planet Runner with blazing firepower - over 25 armaments, including gatling guns, guided missiles, fuel-air mortars and plasma cannons. Become a mech pilot and fight off mysterious alien invaders Various mission types from search and destroy to escorting convoys A great number of weapons and mech upgrades' FROM games WHERE igdb_id = 220 ON CONFLICT (game_id, language_code) DO NOTHING;
