INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ganbare-goemon-uchuu-kaizoku-akogingu', 44808, '1996-03-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co56s4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3sop.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ganbare Goemon: Uchuu Kaizoku Akogingu', 'Ganbare Goemon: Uchuu Kaizoku Akogingu is a Ganbare Goemon game released for the PlayStation on March 22, 1996. This is the first Goemon game since Sasuke and Yae''s appearance as playable characters that doesn''t include either on the playable roster. Instead, they are replaced by the new characters Goroku and Baban. Although Sasuke and Yae are playable characters again in most future games and Goroku and Baban are never seen, mentioned or heard from again after this game. Its unknown why they never appear again, but it is assumed that many fans were upset over Sasuke and Yae being replaced. Gameplay is rather similar to Ganbare Goemon 3, as there''s a main map in top-down perspective, which leads to various 2-D sidescrolling levels.' FROM games WHERE igdb_id = 44808 ON CONFLICT (game_id, language_code) DO NOTHING;
