INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Don''t Know Jack Vol. 2', 'You Don''t Know Jack Vol. 2 is the mutant offspring of the original fast-paced trivia game where you are a contestant on a manic game show. With all the excitement of the first game, lots of mind-blowing surprises, plus four additional question types, volume 2 will scrape the trivia out of your cranium like the seedy pulp from a melon.' FROM games WHERE igdb_id = 16782 ON CONFLICT (game_id, language_code) DO NOTHING;
