INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('neo-drift-out-new-technology', 39600, '1996-03-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobmco.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5fx2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neo Drift Out: New Technology', 'This is an arcade-style rallying game with a particular isometric view. To start, players chooses between three big Japanese rally-spec vehicles—the Mitsubishi Lancer, the Subaru Impreza, and the Toyota Celica—which vary in their Speed, Control, and Body stats. In each racing stage, the player needs to get to the finish line in the shortest time possible. If the clock hits zero, the player loses and the game is over unless they can continue. While driving, the time is hindered by barrels, puddles, slippery ice, cones and other obstacles in the player''s path. Even other cars driving can be an obstacle. Also the player has to keep straight when driving up slopes, or the car will swerve and crash. The player can gain more time if they make it through checkpoints in between the starting and finishing points. The player can also take shortcuts. Before making a turn, the player will always get an immediate warning on the screen with a voice saying which direction the player ought to turn and certain warnings. Aside from the starting Practice stage, there are six other stages to be conquered: European, African, Snow Land, Southern Hemisphere, Scandinavian, and Great Britain.' FROM games WHERE igdb_id = 39600 ON CONFLICT (game_id, language_code) DO NOTHING;
