INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wonder Project J2: Corlo no Mori no Josette', 'Wonder Project J2 takes place 15 years after the events of the first Wonder Project J game and focuses on a gijin (robot) girl named Josette. The game begins with Josette leaving her home on Corlo Island and traveling to Blueland, where she must learn to behave like a human and ultimately stop an empire from destroying the world.' FROM games WHERE igdb_id = 47748 ON CONFLICT (game_id, language_code) DO NOTHING;
