INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Koutetsu Reiiki: Steeldom', 'Koutetsu Reiiki: Steeldom (also known as just "Steeldom") is a third-person arena-based action game and a follow-up to Reverthion by the same developers. It plays very similarly to Sega''s Virtual On, and includes eight playable characters each with their own unique moveset and abilities. There is a single-player campaign with unique endings for each character, as well as a 2-player split screen versus mode; the Saturn version adds system link support for two-player matches between two consoles.' FROM games WHERE igdb_id = 43813 ON CONFLICT (game_id, language_code) DO NOTHING;
