INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3-D Ultra Pinball: Creep Night', 'Pinball with a strong horror motif. In the 3-D Ultra Pinball tradition, many of the effects achieved on these tables could not be reproduced on traditional machines. There are even cutaways to mini-video games where you can rack up bonus points. Tables can be played individually, or all at once in a campaign to beat them.' FROM games WHERE igdb_id = 50471 ON CONFLICT (game_id, language_code) DO NOTHING;
