INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drowned God: Conspiracy of the Ages', 'Drowned God: Conspiracy of the Ages is a 1996 science fiction adventure game developed by Epic Multimedia Group and published by Inscape. The game propounds the conspiracy theory that all of human history is a lie and that the human race''s development and evolution were aided by extraterrestrials. The player attempts to uncover the truth through the course of the game by traveling to a variety of different worlds, interacting with historical and fictional characters, and solving puzzles.' FROM games WHERE igdb_id = 12421 ON CONFLICT (game_id, language_code) DO NOTHING;
