INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avengers in Galactic Storm', 'Avengers in Galactic Storm is a 1995 fighting arcade game based on characters in the Marvel universe, primarily the Avengers but also the Kree. The game''s plot and roster of playable characters are based on the Operation: Galactic Storm story arc. This was one of Data East''s last fighting games, as well as their third and last game based on The Avengers.' FROM games WHERE igdb_id = 39361 ON CONFLICT (game_id, language_code) DO NOTHING;
