INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clue', 'Clue is a full-motion video adaptation of the popular board game of the same name. It is an amalgamation of two earlier CD-i titles where (up to six) players take turns investigating a mansion where a murder happened, uncovering clues and evidence to reveal the assassin. There are three storylines with four difficulty levels, each with a unique solution making it altogether twelve different mysteries: Deadly Patent (from Clue), The Road to Damascus and Blackmail (both from Clue 2: The Mysteries Continue).' FROM games WHERE igdb_id = 206977 ON CONFLICT (game_id, language_code) DO NOTHING;
