INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Materia Magica', 'Welcome to Materia Magica, an online fantasy game where your imagination is the only system requirement. For over two decades, our players have journeyed to the magical world of Alyria for adventures in fun, old-school, multiplayer text-based gaming. It’s completely free to play: no ads, no in-app purchases required.' FROM games WHERE igdb_id = 137179 ON CONFLICT (game_id, language_code) DO NOTHING;
