INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('twilight-syndrome-tansaku-hen', 65452, '1996-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2wb3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm6cf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twilight Syndrome Tansaku-hen', 'Every high-school has its own dark secrets. Well, maybe not every; but in Japan, this seems to be a rather popular theme. Mysterious disappearances, ghostly photographs, untimely deaths, eerie sounds coming out of the music room - all these things attract the curiosity of three high-school girls: Yukari, Mika, and Chisato. At night, armed with nothing but a flashlight, the trio of heroines enters the dark school building, prepared to explore every corner, and investigate every urban legend they have heard of... Tansaku-hen opens the Twilight Syndrome horror adventure series, defining its stylistic traits and gameplay. The game is divided into chapters, each dedicated to a particular "ghostly" story. Unlike most Japanese-style adventures, there is physical character navigation in the game; the player moves digitized images of the three girls on 2D backgrounds, in a manner somewhat similar to side-scrolling games - though many areas feature a third dimension, like in Western third-person perspective adventures. The gameplay consists of two activities only: walking and occasionally choosing a dialogue option and/or action, as prompted by the game''s narrative. There is no other kind of interaction, no inventory, and no combat. Different choices may lead to different endings; the next chapter can be accessed only if the player has not attained the "bad" ending. Twilight Syndrome: Tansaku-hen abandons the nearly omnipresent anime/manga graphical style of Japanese games in favor of digitized images and photos of real people.' FROM games WHERE igdb_id = 65452 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 65452 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
