INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cricket 96', 'One of the first realistic cricket games in the market, Cricket 96 wowed people with its options, commentary and video options. You can play either test or one-day matches with a choice of 8 teams, and you can set your field, bowlers and batsmen. It has a good control system and decent graphics for its time.' FROM games WHERE igdb_id = 94684 ON CONFLICT (game_id, language_code) DO NOTHING;
