INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hissatsu!', 'The game is an action platformer similar to Sega''s Shinobi series where the player controls four assassins on different assignments in feudal Japan. Each assassin has different attacks, and the player chooses two of the assassins before each stage and can switch between them at any point during gameplay. Each stage involves assassinating a different target, who is typically protected by a bodyguard that is stronger than a normal enemy, and there are story scenes preceding and following every stage.' FROM games WHERE igdb_id = 269158 ON CONFLICT (game_id, language_code) DO NOTHING;
