INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akagi: Touhaiden', 'Based on Nobuyuki Fukumoto''s manga "Akagi: Yami ni Oritatta Tensai" and some live-action adaptations, the game explores the gambling exploits of Shigeru Akagi. The player progresses the story by winning Mahjong games in two to four player matches with the stakes gradually rising through each new game, with the goal of become a legendary champion.' FROM games WHERE igdb_id = 254431 ON CONFLICT (game_id, language_code) DO NOTHING;
