INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toffifee: Fantasy Forest', 'Toffifee Fantasy Forest was released in 1996 as a promotional game for advertising Toffifee, a product of Merci GmbH & Co, Berlin. Toffifee Fantasy Forest is about a dwarf''s journey to save his friends from the hands of an evil magician. He has to find his way through a forest and a cave to arrive finally at the wizard''s castle. It''s a classic, jump ''n'' run, side scrolling, arcade game. You can collect goodies for scorepoints and Toffifees (a kind of chocolate). With Toffifee you can buy nuts (for hitpoints) and fir cones/stones (used as ammunition to be thrown).' FROM games WHERE igdb_id = 325938 ON CONFLICT (game_id, language_code) DO NOTHING;
