INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jinyong Qunxia Zhuan', 'Jinyong Qunxia Zhuan is a semi-humorous RPG set in a world which is populated by familiar characters from different novels by the famous Chinese writer Jinyong. Navigating your hero from isometric perspective, you encounter various characters that will join your party. During battles, you can move your characters on the combat screen within their movement ranges. You can attack with melee weapons when standing near the enemy, or use spells and techniques from a distance. There are no random battles in the game, and most of the battles are pre-set.' FROM games WHERE igdb_id = 78043 ON CONFLICT (game_id, language_code) DO NOTHING;
