INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Series Baseball ''96', 'World Series Baseball ''96 is a follow-up to the previous two Genesis games in the series with the rosters and stats of the 1995 MLB season as well as the schedule for the 1996 season. It has all 700 players and 28 teams and stadiums. The game types include Exhibition, League, Playoffs, Batting Practice, Homerun Derby, and Classic Homerun Derby. There is also a possibility to play an All-Star game. Trading can be enabled or disabled and the season length options are 13, 26, 52, 104 and 162.' FROM games WHERE igdb_id = 46685 ON CONFLICT (game_id, language_code) DO NOTHING;
