INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fangs Out 2', 'In this early 3D vector shooter by Kenta Cho (ABA), you pilot a space fighter battling increasingly challenging waves of enemy ships. The game uses flight-sim controls, multiple view modes, and simplified physics simulation, much like earlier influences such as Star Luster. You have both lasers and lock-on missiles for eliminating all 12 types of enemies. Protect your comrades, take down those cruisers, and aim for the highest scores!' FROM games WHERE igdb_id = 240257 ON CONFLICT (game_id, language_code) DO NOTHING;
