INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GeoSafari: Animals', 'Geosafari: Animals is an educational game about animals for ages 8 and up. There are sixteen games available: Animal Hall of Fame, Shark!, Animals Sound Off!, Geosafari Dog Show, Skulls, Name that Bird Call, Reptiles, Micro Mysteries, Horse Round-Up, Endangered Animals, Animal Art Gallery, Whale Watch, Animal Eye-D, Weird World of Animals and GeoChallenge. There are pictures, illustrations and even videos.' FROM games WHERE igdb_id = 79629 ON CONFLICT (game_id, language_code) DO NOTHING;
