INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simulation Zoo', 'Simulation Zoo is, as the name suggests, a business simulation game similar to the well-known Theme Park, in which the player operates and manages a zoo. The player is a new CEO brought in to turn around a failing zoo, maintaining and expanding facilities, balancing income and expenses, and acquiring new exhibits. The game is viewed from an isometric perspective and proceeds in real-time. There are eight different scenarios to choose from, each focusing on a different biome such as river valley, jungle, or desert.' FROM games WHERE igdb_id = 97987 ON CONFLICT (game_id, language_code) DO NOTHING;
