INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('trouble-with-trolls', 122638, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co83nk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc75w8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trouble With Trolls', '"The Trouble With Trolls" - or at least so my old Mum used to keep telling me - was that they simply never knew when to give up. If they found themselves faced with a plateful of best, prime quality "deviled orc''s eyes" then they would just sit there and eat them all until they were sick. Or else they would do battle with their strongest enemies until neither of them were capable of swinging another blow. Worse still, they held on to their gold with a grip that few could break and had even been known to lay down their very life to protect it or to take yours in the process!!! As for getting them to part with treasure such as diamonds and pearls that was almost a task beyond the talents of even the most ardent of the adventurers that chose to undertake it. So it was that such a task needed to be carried out and so it was that BRIAN WOODLOUSE was the poor unfortunate sod that had to do it.' FROM games WHERE igdb_id = 122638 ON CONFLICT (game_id, language_code) DO NOTHING;
