INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost in the Amazon', 'Lost in the Amazon is an interactive CD-ROM based on the book of the same name by Toni Brandão, which provides lots of information about the region''s indigenous people, animals, and plants. It also includes two games: a matching card game between animals or plants and a Frogger-style where you need to bring items back to the tent.' FROM games WHERE igdb_id = 296057 ON CONFLICT (game_id, language_code) DO NOTHING;
