INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('money-town', 47294, '1996-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dqnckg9wd9pmrnkytbdy.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Money Town', 'The fun way to teach kids the value of money.  Fun and funds go hand in hand when you put your money where your mouth is- with Money Town, the joy-filled multimedia adventure that teaches your child all the basics about dollars and cents.  As kids help Greenstreet''s coolest characters earn money to reopen their town park, they''ll click-and-discover a merry world full of animated money facts, figures, songs and surprises that will send them giggling all the way to the bank. Money Town is guaranteed to give your children a foundation in finances they and you will value forever.  Inspired by the popular children''s book "The Kid''s Money Book" written by Neale Godfrey, Money Town features five engaging activities that will help your child learn:  - Basic money math.  - Coin recognition.  - How to make change.  - How to save and spend wisely.  - Simple money management.  - Fun money facts and history.  Highlights:  Funny, friendly characters take kids on a learn-and-earn adventure.  Five engaging, interactive games combine learning and laughter.  Loaded with dazzling animations, digitized speech and sound effects.  Five original sing-along songs by acclaimed children''s performer Dave Kinnoin.  CD includes Neale Godfrey''s "Video Tips for Parents," with advice from the best-selling author of Money Doesn''t Grow On Trees.  Learn coin recognition and making change at the Opportunity Knocking Emporium.  Learn money facts and history at Penny''s Quiz Show.  Earn money as you help Ona Budget recycle.  Learn coin identification and addition in Buck''s field goal game.' FROM games WHERE igdb_id = 47294 ON CONFLICT (game_id, language_code) DO NOTHING;
