INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('amazon-trail-ii', 65850, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9c99.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv7k8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amazon Trail II', 'Amazon Trail II is an educational game and the sequel to The Amazon Trail. In this game you have to canoe up the Amazon River. Before starting, it is obligatory to choose yourself a guide - each of the four available candidates has a special skill that may help you on your journey. In the course of the game, you need to manage the supplies; meet, talk, and trade with different people presented by live actors in FMV; read maps; and decide how much to eat, when to rest, and how fast to paddle. The game also contains a huge amount of information about the science and history of the Amazon rainforest. It is possible to explore the rainforest along the route spotting one of 100 different species and taking pictures or picking up fruits for the supply. There is a fishing mini-game as well, and six more learning games where kids learn the origins of commodities like coffee, rice, and chocolate, locate the major rivers of the world etc.' FROM games WHERE igdb_id = 65850 ON CONFLICT (game_id, language_code) DO NOTHING;
