INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantei Jinguji Saburo: Mikan no Report', 'Tantei Jingūji Saburō ~ Mikan no Rupo is a Japanese style adventure game in the detective/mystery genre. It is the 5th game in the Jake Hunter / Tantei Jingūji Saburō series, being released between Toki no Sugiyuku Mama ni... (1990) and Yume no Owari ni (1998). While following the same formula of the previous titles, the game features a "Zapping System", allowing the player to see the story from the perspective of other characters as well as Jingūji. Also featured in this title is car chase and following suspects in the form of 3D mini-games, although these features would rarely be seen again in future releases.' FROM games WHERE igdb_id = 78561 ON CONFLICT (game_id, language_code) DO NOTHING;
