INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('strike-point', 44964, '1996-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ke3tloazpnawvtnjlpej.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strike Point', 'The terrorist organization named Hex has placed deadly ShockWave devices worldwide. If triggered, they will cause total destruction of the ecosystem. You must lead the newly formed StrikePoint helicopter team against the forces of Hex, destroying their strongholds and defusing their tectonic threats. The game contains 10 global hotspots that you can attempt in any order you choose. Each hotspot contains its own set of missions. Some of the missions you will be sent on will involve destruction of enemy aircraft and artillery, ambushing and elimination of enemy convoys, rescuing of ally scientists, and most importantly collecting and defusing all untriggered ShockWave devices. You can choose to fly one of three different types of helicopters to accomplish your goals.' FROM games WHERE igdb_id = 44964 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 44964 AND p.igdb_id = 7 ON CONFLICT DO NOTHING;
