INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WCW vs. the World', 'HOT WRESTLING ACTION! Chris Benoit, Lex Luger, Dean Malenko, Ric Flair, Eddy Guerrero, Hulk Hogan. Also appearing: Sting, Rick Steiner, Scott Steiner, Ultimo Dragon, Masahiro Chono, Lord Steven Regal... and more! Wrestle the world''s toughest WCW wrestlers. Control non-stop 3-D action in and out of the ring! 15 of your favorite WCW superstars 60 wrestlers from 6 different organizations 30 to 40 moves per wrestler Over 10 hot 3-D arenas' FROM games WHERE igdb_id = 18316 ON CONFLICT (game_id, language_code) DO NOTHING;
