INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rebel Runner: Operation - Digital Code', 'The planet Ranax is under attack from the evil Maaron empire. The last Ranaxian soldier must find and use a digital code to shut down the empire''s mind-controlling satellite. Rebel Runner - Operation: Digital Code is an arcade game where the main character shoots fireballs from his hands at extraterrestrial enemies, while crossing pre-rendered 3D levels. The character is controlled by either the keyboard (default buttons: CTRL for fire and ALT for jumping) or joystick. Each stage starts with three lives and the game saves progress between levels.' FROM games WHERE igdb_id = 209258 ON CONFLICT (game_id, language_code) DO NOTHING;
