INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('flame-zapper-kotsujin', 144086, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4m7a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgfnk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flame Zapper Kotsujin', 'Flame Zapper Kotsujin is a vertical shooter which takes place in outer space. The player controls a fighter spacecraft, advancing through five large levels swarming with enemies (space ships, turrets, tanks, etc.), each culminating with a boss battle. The spacecraft is armed with primary and secondary weapons (fired simultaneously), as well as powerful bomb attacks. Each of these comes in three varieties distinguished by color: red, yellow, and purple. The red group of weapons focuses on spraying fire in different directions; the yellow group contains powerful weapons without covering much of the screen; the purple group is composed of homing lasers and missiles. Power-ups usually stay on screen for a while, changing their color properties.' FROM games WHERE igdb_id = 144086 ON CONFLICT (game_id, language_code) DO NOTHING;
