INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harpoon Classic ''97', 'Harpoon Classic ''97 is a revised version of traditional Harpoon Classic which is in turn, based on Larry Bond''s original and very popular Harpoon board-game from 1980. The core gameplay is top-down (map and menu based) ultra-realistic strategic naval warfare wrapping around scenarios in 4 different theatres (North Atlantic, Greenland/Iceland, Indian Ocean, and Persian Gulf/Mediterranean).' FROM games WHERE igdb_id = 94487 ON CONFLICT (game_id, language_code) DO NOTHING;
