INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Case for Cap & Co', 'Karen Lucre is in a fix! Zak, her little dog has been kidnapped! The kidnappers are asking for a huge ransom. Zak is in a great danger. Time is running out and Karen''s parents are on holiday... it''s obviously A Case for Cap and Co! Together with Cap, Billy, Karen and Toby you must comb the town of Roseborough for clues. Who are the kidnappers? Where is poor Zak being held? Can you help free him in time?' FROM games WHERE igdb_id = 242642 ON CONFLICT (game_id, language_code) DO NOTHING;
