INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hind', 214650, '1996-01-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co54q0.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hind', 'From the main menu the player can choose single missions (playing either alone or in networked multiplayer), a campaign consisting of missions strung together or to undergo training at the Soviet airbase at Saratov. The training is very extensive and teaches the use of weapons and avionics systems, navigation, battle tactics etc. Combat can take place in three locales: Kazakhstan, Korea or Afghanistan. The Campaign mode features video clips as well as a detailed briefing before each mission, complete with a mission description, a detailed map and the ability to choose the desired ordnance. The flight itself can be in novice mode, stable mode and realistic mode.' FROM games WHERE igdb_id = 214650 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 214650 AND p.igdb_id = 13 ON CONFLICT DO NOTHING;
