INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Worlds.com', 'The registered version was released in 1996 as "Worlds Chat Gold" for Windows 3.1 & 95. It was eventually superseded in 1998 by "Worlds Ultimate 3D Chat [Plus…]" for Windows 95, which contained the software "WorldsBrowser" (later known as "WorldsPlayer").' FROM games WHERE igdb_id = 130418 ON CONFLICT (game_id, language_code) DO NOTHING;
