INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Versailles 1685', 'Stop a conspiracy to sabotage Louis XIV''s rule, as you explore and adventure your way through 1685 Versailles. The game was a commercial success, with sales of 500,000 units in Europe alone by 2000.' FROM games WHERE igdb_id = 2221 ON CONFLICT (game_id, language_code) DO NOTHING;
