INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moraff''s Escapade', 'Moraff''s Escapade is a single player, shareware, arcade / puzzle game based on Lode Runner. The game consists of a series of vertical ladders and horizontal platforms. Scattered around the game area are gemstones and the object of the game is to collect all the gems on a level in order to progress to the next. However the players progress is made more complex by the presence of Flesh Eaters who track the player and attempt to eat him/her.' FROM games WHERE igdb_id = 135666 ON CONFLICT (game_id, language_code) DO NOTHING;
