INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legends of Kesmai', 'Legends of Kesmai (LOK) was among the first successful graphical multi-player online role-playing games. It was based on a slightly stripped down version of Island of Kesmai with 2D sprites replacing IoK''s roguelike pseudo-graphics, and was available for play at America Online and GameStorm. Prior to that, Kesmai corporation ran a long open beta for the game, as well as hosting the game for a short period of time in the mid 1990s. In 1999 Electronic Arts bought Kesmai and in 2000 closed the business.' FROM games WHERE igdb_id = 196764 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 196764 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
