INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eisei Meijin II', 'Eisei Meijin II is a digital conversion of the traditional Japanese board game Shogi for one or two players, and the second game in the series to appear on consoles. It is very similar to the previous release, offering all of the same features: play against the computer or a second player, recording and playback of matches, playable records of historical matches, and a Tsume Shogi solver tool. New in this updated version of the game are: • An improved move prediction tool with faster performance • A new extra-easy "Level 0" difficulty option • Additional historical matches available for replay' FROM games WHERE igdb_id = 268640 ON CONFLICT (game_id, language_code) DO NOTHING;
