INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Watchtower', 'War has never been as deadly. Deadly military weapons to pick-up: Pistol, Kalashnikov, Uzi, Assault Rifle, Sub-Machine Gun, Minigun, Flame Thrower, Rocket Launcher, and Grenades to lob! Six long and challenging missions in different areas of the world with three different terrain types: Desert, Jungle, and City. Armies of ruthless enemies and vicious end of level guardians that show no mercy! Heavily armed enemy vehicles and aircraft including tanks, helicopters, trucks, submarines, and jets. Lots of lead and fun guaranteed.' FROM games WHERE igdb_id = 15568 ON CONFLICT (game_id, language_code) DO NOTHING;
