INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sei Shoujo Sentai Lakers III', 'In the sequel to Sei Shōjo Sentai Lakers II Akira and his team have successfully fended off Rayott''s assault and are enjoying a brief peaceful time. However, an enigmatic masked enemy known as Neos Bullard appears on the stage. Aiming to capture the power of Laker crystals, Neos Bullard and his minions invade Earth, taking the Lakers by surprise.' FROM games WHERE igdb_id = 264324 ON CONFLICT (game_id, language_code) DO NOTHING;
