INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sea Bass Fishing', 'Sea Bass Fishing is a fishing game developed by Victor Entertainment for the Sega Saturn. It was not released in North America. It is not the same game as the 1998 Sea Bass Fishing, released for Sega Titan Video arcade hardware. The game would be followed by Sea Bass Fishing 2, a Japanese exclusive.' FROM games WHERE igdb_id = 176136 ON CONFLICT (game_id, language_code) DO NOTHING;
