INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nemac IV', 'In order to prevent nuclear armageddon, the player has to immerse with a remotley controled mecha inside of the bunker in which the AI Nemac IV is planning world war iii.' FROM games WHERE igdb_id = 138259 ON CONFLICT (game_id, language_code) DO NOTHING;
