INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amber: Journeys Beyond', 'AMBER is short for Astral Mobility by Electromagnetic Resonance device invented by a promising scientist in the field of paranormal activities, Dr. Roxanna. In order to conduct the experimental testings of the device she secludes herself into an abandoned mansion, rumored to be haunted by ghosts and spirits. In her research Roxanna confirms those rumors, however, fails to respond on numerous phone calls. Her friend, Joe, presumes that something might has happened to her and asks you, the player, to investigate.' FROM games WHERE igdb_id = 12390 ON CONFLICT (game_id, language_code) DO NOTHING;
