INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barrack', 'A JezzBall clone with delightful gameplay additions and beautiful artwork.  Official description: Barrack''s goal is deceptively simple; there are a number of balls on the play field that are bouncing like a neurotic on a sugar rush. Your job is to use your shooter to isolate them. Sounds easy, right?' FROM games WHERE igdb_id = 83919 ON CONFLICT (game_id, language_code) DO NOTHING;
