INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Skidmarks Data Disks', 'This package adds a number of new features to the chaotic and thrilling racing game Super Skidmarks. The major additions are 2 new track disks, featuring a total of 12 new tracks (taking the game up to 36), featuring the succession of loops, jumps and crossovers of the original. In addition, the track disks are now fully hard-disk installable (the program and car disks always were). The program disk has been replaced with an updated one, featuring two new difficulty levels and new championships to take advantage of the new tracks.' FROM games WHERE igdb_id = 78315 ON CONFLICT (game_id, language_code) DO NOTHING;
