INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gustavinho em O Enigma da Esfinge', 'Gustavinho em O Enigma da Esfinge is a 1996 Brazilian adventure game developed by 44 Bico Largo and Ale McHaddo, featuring Brazilian TV star Marisa Orth as Cleopatra. The game follows the adventures of a boy named Gustavinho, who is transported to Ancient Egypt after calling an old man a mummy. To find his way home, Gustavinho must overcome numerous challenges on his journey through Africa and Europe, meeting historical figures such as Julius Caesar and Cleopatra.' FROM games WHERE igdb_id = 28043 ON CONFLICT (game_id, language_code) DO NOTHING;
