INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Jetsons: Space Race', 'A simple, slick side-scrolling platformer starring The Jetsons, everyone''s favorite space age family. George is running late and there''s bumper-to-bumper traffic on the intergalactic interstate. But he still has to drop off Elroy at the Little Dipper School, Judy at Orbit City High, Astro at the Galaxy K-9 School, and Jane at the Shopping Center. All before heading to work. Will he make it to Spacely Sprockets on time?' FROM games WHERE igdb_id = 263937 ON CONFLICT (game_id, language_code) DO NOTHING;
