INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bass Masters Classic: Pro Edition', 'Bass Masters Classic: Pro Edition is an enhanced version of Bass Masters Classic. This game was released for both the Super Nintendo Entertainment System and the Sega Genesis video game devices. Don''t miss your chance to compete in the most realistic fishing game for the Genesis. Featuring pro bass anglers George Cochran, Shaw Grigsby Jr., Gary Klein, Tom Mann Jr., Dee Thomas and Kevin VanDam, BASS MASTERS CLASSIC PRO EDITION brings world championship bass fishing indoors! Compete as one of six actual pro fishermen or as an amateur enthusiast in the Bass Masters Classic. Fish the waters in five three-day tournaments at five different lakes. Rich graphics recreate the outdoor fishing experience in vivid detail. Choose your rod, reel, lure, and even boat engine.' FROM games WHERE igdb_id = 46285 ON CONFLICT (game_id, language_code) DO NOTHING;
