INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer Dragoon Mini', 'One thousand years into the future, you live in constant fear of the Dark Dragon and his giant cyborg insect armies. Armed with a deadly weapon from the ancient past and the guidance of your armored blue dragon, you must save your people from endless swarms of deadly foes. Fulfill your destiny and keep the Dark Dragon from reaching the tower; or die trying.' FROM games WHERE igdb_id = 1670 ON CONFLICT (game_id, language_code) DO NOTHING;
