INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Athena no Kateiban: Family Games', 'Variety game collection was recorded board game of nostalgia. I record five sugoroku like to play using the board that mimics of Othello-like "Reversi", the luster of diamond "King Diamond", hat up game "Kopit", "rocket", the Game of Life-style of "Bankers". Can be simultaneously play up to four people maximum. Let Moriagaro in the good old game a long time ago!' FROM games WHERE igdb_id = 285988 ON CONFLICT (game_id, language_code) DO NOTHING;
