INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PC Collection', 'This game is a small collection of ten different mini-game activities. Those activities include a word processor, a paint and illustration program, a music composer, a fortune-telling screen with printable charms, a simple fashion designer, jigsaw puzzles, a crane machine game, animal dress up, a calendar, and an address book. The game came packaged with the Loopy Mouse.' FROM games WHERE igdb_id = 79443 ON CONFLICT (game_id, language_code) DO NOTHING;
