INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Woodspell', 'Woodspell is a mixture of an adventure-like puzzle-solving game and an activity center with educational elements. The game contains various puzzles, such as matching the sound of a song or the classic "fit the right objects in the correct location" variant. Players also hear stories set in the woodland, filled with elves and fairies, or even print and color the locations they see. The game features hand-drawn scenarios and characters, and original music by the Italian band Tazenda.' FROM games WHERE igdb_id = 92959 ON CONFLICT (game_id, language_code) DO NOTHING;
