INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frobozz Magic Support', 'You play as a novice glyph support clerk but no one''s around but an animated burin. It seems the more experienced support clerks are either lost, got themselves un-implemented, or got stuck in a timeloop. And, of course, everyone else in Zork wants assistance too. No one said your first day on the job would be easy!' FROM games WHERE igdb_id = 217781 ON CONFLICT (game_id, language_code) DO NOTHING;
