INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sound Novel Tsukuuru', 'Sound Novel Tsukuuru is a Miscellaneous game, developed by Success and published by ASCII Entertainment, which was released in Japan in 1996. It is a Satellaview-compatible Slotted Cartridge game belonging to ASCII''s Tsukūru series. The title of these games are portmanteau-word puns mixing the Japanese word tsukuru (作る), which means "make" or "create", with tsūru (ツール), the Japanese transcription of the English word "tool". As the title suggests, this title is a sound novel creation tool.' FROM games WHERE igdb_id = 37851 ON CONFLICT (game_id, language_code) DO NOTHING;
