INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fight for Life', 'Life in the afterlife can be a nightmare for anybody -- especially if real life was a mess. In the Spectre Zone, eight people compete in the annual Hell Fighting Tournament for the amusement of the Gatekeeper. The prize is a second chance at life! Defeat each opponent and steal two of their special fighting moves to prepare for the final challenge -- a battle against the son of the devil himself. Show no mercy. There will be only one victor, only one new life... it must be yours!' FROM games WHERE igdb_id = 40800 ON CONFLICT (game_id, language_code) DO NOTHING;
