INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Who Is Oscar Lake?', 'Released internationally in 1995 and developed by Jersey COW Software, Who Is Oscar Lake? is widely regarded as the first hybrid adventure game/language learning tool. Its simple point-and-click mechanics, liberal use of recorded speech, and mix of pre-rendered backgrounds with live action video represent common development techniques of the 1990s.' FROM games WHERE igdb_id = 72622 ON CONFLICT (game_id, language_code) DO NOTHING;
