INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pebble Beach no Hatou New: Tournament Edition', 'The final golf game for SNES from T&E Soft. The cartridge contains the SA-1 enhancement chip, so there are less waits during gameplay, graphics are also improved. In previous work, the terrain that had been drawn as flat polygon became a more of a pointillist style painting. There were many interface improvements and the main controls moved from a window to being displayed around the player sprite.' FROM games WHERE igdb_id = 38143 ON CONFLICT (game_id, language_code) DO NOTHING;
