INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 Manager', 'Manage your team through the 1996 championship and beyond. Choose to go for glory right away or build your team and keep it at the top for the next decade. With full management control of engineers, contracts, sponsors, training, negotiations, drivers, merchandising, design, development, testing and race weekends it is up to you to get your team to the top!' FROM games WHERE igdb_id = 213266 ON CONFLICT (game_id, language_code) DO NOTHING;
