INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Namco Tennis Smash Court', 'Namco Tennis Smash Court is the first game in the Smash Court series for the Playstation One consoles made by Namco. In the game the player controls a tennis player and can compete in different competitions like tournament, single or double games, etc. The game features different game modes and a good selection of characters to choose, 2D cartoon graphics and a fast and easy gameplay since the game is easy to control but takes time to master. Up to 4 players to play at the same time with the Multitap feature.' FROM games WHERE igdb_id = 74301 ON CONFLICT (game_id, language_code) DO NOTHING;
