INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Allied General', 'Imagine that you are an Allied General. You are the commander of the Allied troops in Europe during World War II, and are the best hope of defeating the Axis forces which have captured Europe and North Africa. Use your strategic knowledge in performing daring invasions, paradrops, naval engagements, and fierce aerial combat for control of the skies. Can you lead and command your units through North Africa, Western Europe, Russia, and ultimately to victory? Glory awaits!' FROM games WHERE igdb_id = 14427 ON CONFLICT (game_id, language_code) DO NOTHING;
