INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Private Eye', 'Humphrey Bogart played him. Robert Mitchum played him. Now it’s your turn to become Philip Marlowe, the world’s most famous private eye! It all starts with an innocent girl who hires you to find her missing brother, but it soon leads to a trail of greed, blackmail, revenge, deceit and murder. Find out who is guilty before the bad guys or the cops get you.' FROM games WHERE igdb_id = 10999 ON CONFLICT (game_id, language_code) DO NOTHING;
