INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nester''s Funky Bowling', 'Nester, the one-time bad boy of comic fame, brings you the funkiest game of bowling you''ll ever experience in 3-D. Finally fans can throw a strike without putting on ill-fitting shoes! Hester, the unknown twin sister, makes her debut appearance. Watch out as the action picks up and the tensions build for these hot-headed bowlers. Their egos clash with outlandish gestures and funky expressions.' FROM games WHERE igdb_id = 20387 ON CONFLICT (game_id, language_code) DO NOTHING;
