INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash', 'Crash is a two-dimensional maze racing game designed and programmed by Edward Valeau of Exidy in 1979. You "control" a car with no brakes which moves at either slow or fast speed through a maze containing dots. At the same time, one or more computer controlled cars run through the same maze in the opposite direction with the intention of ramming you. At each of four junctions in the maze, you have the option of changing lanes to avoid the oncoming cars. The objective is to pick up all the dots before the computer takes you out.' FROM games WHERE igdb_id = 39514 ON CONFLICT (game_id, language_code) DO NOTHING;
