INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ZeiramZone', 'Horizontal scrolling action based on the popular "Zeiram" special effects movie directed by Keita Amemiya. By using the 3D polygon characters and background appearance to achieve dramatic camera work as a movie scene, it becomes a powerful realization. Operate the Bounty Hunter Ilya, and she shall be confronted with the most powerful Zeiram combat organisms.' FROM games WHERE igdb_id = 43809 ON CONFLICT (game_id, language_code) DO NOTHING;
