INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Eternal City', 'This fully text-based roleplaying game takes place in the realistic-fantasy world of Iridine, The Eternal City inspired by Roman history. TEC is wholly immersive and well-worth the investment of getting started. Join for the chance to explore the vast gameworld, complex combat and non-combat mechanics. Stay for the unparalleled community and immersive roleplay. For the right person and the right price, Iridine offers the chance to become anything: gladiator, merchant, acolyte, hunter, bandit, legionary, entertainer, explorer, thief, and so much more.' FROM games WHERE igdb_id = 143241 ON CONFLICT (game_id, language_code) DO NOTHING;
