INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treasure Quest', 'Treasure Quest was a puzzle game in which the player moves from room to room in the mansion of Professor Jonathon William Faulkner, who has bequeathed 1 million dollars to any student who can solve the puzzles he has laid out. To move from one room to the next, players must find a famous quote from visual clues, words and anagrams, and then derive an ultimate solution to the game.' FROM games WHERE igdb_id = 140498 ON CONFLICT (game_id, language_code) DO NOTHING;
