INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kiyeko and the Lost Night', 'This well-thought-out title is an interactive story beautifully narrated by Academy-Award winning actor Ben Kingsley. Kingsley, in the role of the Story Teller, offers a pleasant, pleasurable stroll through an Amazon village and its surroundings. The story follows jungle-boy Kiyeko''s effort to retrieve the Night, stolen by a couple of snakes reminiscent of Disney''s bad-guy animal characters, through 11 different animated scenes - from Kiyeko''s village in the Amazon jungle, through the forest, to the snakes'' lair, and back again. The well-drawn graphics, which integrate 3D backgrounds with 3D animations, and movie-style quality of the title are lovely to look at, regardless of your age.' FROM games WHERE igdb_id = 229281 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 229281 AND ge.slug = 'point-and-click' ON CONFLICT DO NOTHING;
