INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Arena', 'The Arena is a Sub-Game debuting in Kirby Super Star, where the requirement is to the defeat the Main Game bosses and mid-bosses encountered in the title it appears in, with a single life, with limited health benefits. It is similar to Boss Endurance modes, but is generally given more importance, and is always required for 100% completion of the game.' FROM games WHERE igdb_id = 271265 ON CONFLICT (game_id, language_code) DO NOTHING;
