INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Idol Promotion: Yumie Suzuki', 'Idol Promotion: Yumie Suzuki is a simulation game in which the player is the manager of young artists, at the beginning of the game he has to do the scouting for new idol (Yumie Suzuki) and the player''s goal to make her becomes famous nationwide (to gain at least 10,000 fans within 1 year). The game features a bonus second disc that contains Yumie Island, a big collection of clips, movies, photographs of Yumie, making of the game, etc.' FROM games WHERE igdb_id = 209283 ON CONFLICT (game_id, language_code) DO NOTHING;
