INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Pro Wrestling S: 6 Men Scramble', 'Fire Pro Wrestling S: 6 Men Scramble is an entry in Human''s Fire Pro Wrestling series of wrestling games released for the Sega Saturn in 1996 exclusively in Japan. Fire Pro Wrestling S: 6 Man Scramble is the best Pro Wrestling game released in the video game arena. The incredible selection of wrestlers and shoot fighters makes the game interesting even after your 100th match. The RAM that the Saturn possesses allows for several animations for each wrestler. Step into the ring and make mayhem with 6 men scramble!' FROM games WHERE igdb_id = 46092 ON CONFLICT (game_id, language_code) DO NOTHING;
