INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EPS Series Vol. 2: Moonlight to Daybreak - Yukie Nakama', 'The content is a new generation music visual software which recorded 2 original songs + 1 remix of the new artist, 1 photo of still songs, still picture photo collection (about 200 to 300 points), promotion VTR (editing function + director''s cut). Real-life capture technology of PlayStation realizes the beauty of still images and videos! The height of the quality is overwhelming.' FROM games WHERE igdb_id = 286510 ON CONFLICT (game_id, language_code) DO NOTHING;
