INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vehicle Cavalier', 'Fast-paced gun-blazing action awaits in this classic mecha deathmatch. Blast your way through the arena as you wield over 300 types of weapons. You can even create your own weapons for custom carnage! Explore the madness as 8 unique characters are locked in a mobile-suite melee. Conquer all challenges and build the most powerful Vehicle Cavalier ever!' FROM games WHERE igdb_id = 64199 ON CONFLICT (game_id, language_code) DO NOTHING;
