INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Azalta', 'Azalta is an adventure/role-playing game. But unlike most other games of this type, Azalta is much more than a simple single adventure; it is an entire game system with endless adventures, an infinite number of large worlds to explore, hundreds of puzzles to solve, creatures to meet, and items to find -- you can even create your own worlds/creatures/items!' FROM games WHERE igdb_id = 165515 ON CONFLICT (game_id, language_code) DO NOTHING;
