INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunacy', 'Lunacy, released in Europe as Torico and in Japan as Gekka Mugentan Torico (月花霧幻譚 Torico), is an adventure game developed by System Sacom and published by Sega for the Sega Saturn in 1996. Lunacy is an interactive movie adventure consisting of a long series of interconnecting full motion video (FMV) sequences, much like The 7th Guest and System Sacom''s earlier Saturn game, Mansion of Hidden Souls.' FROM games WHERE igdb_id = 71493 ON CONFLICT (game_id, language_code) DO NOTHING;
