INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swigridova kletba', 'Swigridova kletba (Swigrid''s Curse) is a fairy-tale adventure. It is one of the first Czech games that features voice acting, provided by the developer team members themselves. The game is entirely controlled with the mouse through a single action. The gameplay is based on exploring the environment, talking to characters, and solving puzzles. Items can be collected and they are stored in an inventory near the bottom of the screen.' FROM games WHERE igdb_id = 182294 ON CONFLICT (game_id, language_code) DO NOTHING;
