INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1497: Five Years After', '1497: Five Years After is a Colonization/Civilization like strategy game, in which you are sent to explore and conquer the New World for your King. The game begins five years after the discovery of the New World. You are the captain of a cargo ship and your mission is to wipe out all the rivaling European powers from the New World.' FROM games WHERE igdb_id = 38856 ON CONFLICT (game_id, language_code) DO NOTHING;
