INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where in the World Is Carmen Sandiego?', 'Players take on the role of gumshoe and explore the globe tracking down crafty criminals through guided tours of various locales and beautifully painted 360-degree panoramas. The player must use their knowledge to find Carmen Sandiego or any of her innumerable henchmen, all with the help of a searchable database within the game that contains: video clips; essays on each area''s economics, politics and culture; maps; and photographs.' FROM games WHERE igdb_id = 299326 ON CONFLICT (game_id, language_code) DO NOTHING;
