INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mighty Math Zoo Zillions', 'Mighty Math Zoo Zillions teaches kindergarten, 1st, and 2nd grade students the concepts, facts, and thinking skills necessary to build math confidence and develop a strong, lasting understanding of math! Innovative activities teach number line concepts, addition and subtraction, counting money and making change, problem-solving skills, and early three-dimensional geometry. Learning and understanding math is fun with the entertaining creatures of Zoo Zillions!' FROM games WHERE igdb_id = 313286 ON CONFLICT (game_id, language_code) DO NOTHING;
