INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s SSN', 'Tom Clancy''s SSN is a simulation of the 688i (i.e. Los Angeles-class) nuclear hunter/killer submarine. The player commands the USS Cheyenne in a limited war against China over the Spratly Islands in a 15-mission campaign where they''ll perform a wide variety of missions from patrol to escort, from boomer hunt to convoy attack.' FROM games WHERE igdb_id = 57686 ON CONFLICT (game_id, language_code) DO NOTHING;
