INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Synnergist', 'In Synnergist the player takes the role of Tim Machin, an ambitious young journalist forced by cruel circumstances to work for a trashy tabloid newspaper. Set in the year 2010, the game puts the player on the streets of New Arhus—a city of extremes, crammed with both cutting edge technology and the decaying remnants of a once proud past. Very soon, Tim finds himself on the trail of a sinister force that appears to be connected to the crime and killing...' FROM games WHERE igdb_id = 2227 ON CONFLICT (game_id, language_code) DO NOTHING;
