INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jigsaw Island: Japan Graffiti', 'Jigsaw Island is a jigsaw puzzle game, and the third title in Nippon Ichi''s jigsaw series. As in Jigsaw Party and Jigsaw World, it combines the jigsaw puzzle with elements of arcade puzzle games, tasking two players (or a player and the computer) with solving a set of puzzles as quickly as possible. Pieces are supplied to each player in a specific order, and there are also power-ups that can be used to hinder the other player.' FROM games WHERE igdb_id = 123396 ON CONFLICT (game_id, language_code) DO NOTHING;
