INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daytona USA: Championship Circuit Edition', 'Daytona USA Championship Circuit Edition drives home the excitement of speedway racing more than ever before! Slick new full-screen graphics and two brand new extra circuits await as you select any one of eight turbo-charged cars to race in. Split-screen 2-player mode and a host of options including ghost car ensure that Daytona USA Championship Circuit Edition will set the pace in the race to the finish line.' FROM games WHERE igdb_id = 45500 ON CONFLICT (game_id, language_code) DO NOTHING;
