INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Greatest Moments of Our Time', 'Greatest Moments of Our Time is a reference title produced in 1996 and includes an interesting mix of subjects. The main menu has some admin icons plus eight categories, one of which is a trivia game. The quiz has three levels of difficulty. It lasts for three rounds and has five timed, multiple choice questions per round, all the questions are based on the articles in the reference material on the disc.' FROM games WHERE igdb_id = 176078 ON CONFLICT (game_id, language_code) DO NOTHING;
