INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aerial-racers', 76195, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/z6305s0kpavgf8wqrcxl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ogsr0u17jih0k6mkktzz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aerial Racers', 'This is one of the games that came with Amiga Forever, which I highly recommend. I''d define it as slow, sluggish and unresponsive, which is a shame, as the game is an obvious homage to Racing Destruction Set. There is a large number of user-created tracks included, and you can make your own. You can even adjust the gravity (on top of the default "earth" mode, the gravity on tracks can be that of any of the other planets, the moon or the sun). If they had gotten the controls right, this could have been something to write home about.' FROM games WHERE igdb_id = 76195 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 76195 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
