INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lunar-magic-school', 46093, '1996-02-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co47xc.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar Magic School', 'This is a side-story, set in the same world as the famous Lunar RPGs: Silver Star and Eternal Blue. The town of Burg is populated by harvesters, and you take control of two girls, Ellie and Lena. One day, they are sent to the island of Ien where they should study magic, and there begins their adventure. The game is a traditional Japanese-style RPG. You navigate your party through a top-down world, visiting towns and hostile areas. Enemy encounters are random, the battles are turn-based and are viewed from first-person perspective.' FROM games WHERE igdb_id = 46093 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 46093 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 46093 AND p.igdb_id = 32 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ezekial-s-jacksons-amazing-truckology', 201743, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ipn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjdba.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ezekial S. Jackson''s Amazing Truckology', 'Amazing Truckology is a children’s computer game created by Ezekial S. Jackson that teaches children about a variety of trucks. There are four places to explore: the farm, fire station, the quarry, and the building site. Fifteen trucks are included in the game. There are also clickable hotspots in some of the scenes. There are some video clips and animations that shows the player the trucks on how it does and how they work. There are colour photographs on every truck included in the game, as well as some technical information. Four Truck-A-Rama VR scenes are included in the game, as well as 3D animated models of the fifteen trucks included. The player can also simulate driving one of the fifteen trucks in the game as well. The game features background music which has 40 minutes of songs included. Amazing Truckology is suitable for ages 5 and up.' FROM games WHERE igdb_id = 201743 ON CONFLICT (game_id, language_code) DO NOTHING;
