INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harpoon II: Admiral''s Edition', 'Harpoon II: Admiral''s Edition is a naval strategy simulation that expands the original game with seven comprehensive battle sets spanning global and regional conflicts. Players command naval forces through scenarios ranging from Cold War confrontations to regional disputes, with theaters covering multiple parts of the world. The game includes a scenario editor that allows players to create custom naval engagements by designing their own missions, fleets, and combat situations.' FROM games WHERE igdb_id = 73780 ON CONFLICT (game_id, language_code) DO NOTHING;
