INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Menateus', 'Menateus is the official commercial game for the Expo in Hannover, Germany. The game centers around the EXPO 2000 Exhibition, where you have to stop the fog of indifference to save the planet. In doing this, you must travel through time and space. You have to visit the Cyberdome, the palace of elements, the pyramids of mystic. Only if you find all puzzle pieces, you can finish this game.' FROM games WHERE igdb_id = 72168 ON CONFLICT (game_id, language_code) DO NOTHING;
