INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi', 'The Tamagotchi is a handheld digital pet that was created in Japan by Akihiro Yokoi of WiZ and Aki Maita of Bandai. It was released by Bandai on November 23, 1996 in Japan and on May 1, 1997 in the rest of the world, quickly becoming one of the biggest toy fads of the late 1990s and the early 2000s. This version is also officially known as "Gen1" to differentiate it from the later release of "New Species Discovered!! Tamagotchi" also known as "Gen 2".' FROM games WHERE igdb_id = 194325 ON CONFLICT (game_id, language_code) DO NOTHING;
