INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chex Quest 2', 'The Chex Warrior returns to his home planet and lands in Chex City only to discover that the Flemoid threat has reached his homeworld. Grabbing his zorcher, he races to the rescue of his beloved home. He battles through a spaceport (an Earthed space station), a cinema (A movie theater showing 3 looping movies.), a museum (A museum of art, history, and culture.), and the city (Chextropolis) until he reaches the sewers, where he faces The Maximus.' FROM games WHERE igdb_id = 8718 ON CONFLICT (game_id, language_code) DO NOTHING;
