INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lords-of-doom-part-one-the-black-god', 170290, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3tvg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scdg98.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lords of Doom: Part One - The Black God', 'Lords of Doom is a shareware fantasy role-playing game. A prosperous kingdom has been overrun by demons, and now a sole hero controlled by the player must put an end to this invasion and restore peace in the realm. The game uses a custom role-playing system which is based on a number of character attributes and skills the player can build. There are no character classes, and the player may develop fighting, thieving and magic skills based on their choice. Experience points are awarded for exploration, interaction with NPCs and successful combat encounters. The setting is a vast fantasy world with several human kingdoms, also inhabited by various fantasy creatures, including dragons and other monsters, as well as different types of undead. However, humanoid fantasy races like elves or dwarves are not present. The state of human civilization is comparable to that of Ancient Rome, except for the widespread use of magic.' FROM games WHERE igdb_id = 170290 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 170290 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
