INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Play-Doh Creations', 'Your creativity takes shape on Play-Doh Island! It''s creativity and show-and-tell at its best! Hop aboard the Play-Doh Island express and travel to four different creation locations. Invent all kinds of creatures at the Laboratory. Design their costumes and hair styles at the Mini Mall. Craft crazy vehicles at the Factory. Mix up some delicious Play-Doh treats at the Bakery. Then...it''s showtime at the theater! Play-Doh Pete hosts "The Great Doh Show" musical review starring YOUR animated creations!' FROM games WHERE igdb_id = 270611 ON CONFLICT (game_id, language_code) DO NOTHING;
