INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conquest of the New World: Deluxe Edition', 'Conquest of the new world is a turn-based strategy game that lets you control one of 6 different nations in their attempt to colonize the new continent. The gameworld is represented in an isometric point of view. Combat is a mini-game taking place on a battlefield where victory can be achieved by killing enemy troops or capturing the enemy''s flag. This deluxe edition added new elements of diplomacy, including trade options, as well as specific bonuses based on which nation is played.' FROM games WHERE igdb_id = 2616 ON CONFLICT (game_id, language_code) DO NOTHING;
