INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Macro-TV', '"MACRO-TV" is a 1996 Japanese sci-fi point-and-click game developed by the three-person studio MACRO-ARTS. Armed with the "MACRO-TV" system, players investigate the activities of hacker David Browith. Utilizing built-in CCD cameras and an ultra high-speed network, players navigate the dangers of cyberspace, unraveling the mysteries behind Browith''s intrusion and his peculiar world.' FROM games WHERE igdb_id = 278071 ON CONFLICT (game_id, language_code) DO NOTHING;
