INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wally wo Sagase!', 'Wally wo Sagase! is a 1992 arcade game by Sega for the Sega System 18 tying into the Where''s Wally? (Where''s Waldo? in the US) media franchise. You use a trackball to find Wally in a number of different ways (catching him in an animation, finding him in a door, finding him with only a small portion of the screen visible at a time, etc.). It is only known to have been released in Japan, however most people use the translated name Where''s Wally!; whether or not there was an overseas release is unknown (TODO find proof).' FROM games WHERE igdb_id = 40530 ON CONFLICT (game_id, language_code) DO NOTHING;
