INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Gene Machine', 'Piers Featherstonehaugh and his faithful servant, Mossop, arrive back home to discover a talking cat on their doorstep. The cat tells them of an outlandish plot concerning genetic mutations gone haywire. It then becomes Featherstonehaugh goal to stop this ghastly activity and to catch the fiends behind it.' FROM games WHERE igdb_id = 19672 ON CONFLICT (game_id, language_code) DO NOTHING;
