INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PC Selección Española de Fútbol Eurocopa ''96', 'PC Selección Española de Fútbol Eurocopa ''96 is the first of Dinamic Multimedia''s international competition-based games, in which you will have the possibility of being the Spanish national coach. For that, you dispose of a huge list with all the (Spanish) Primera División players, the responsibility of designing the team formation and tactics, or if you prefer, organizing a friendly match. But that''s not all. You can also choose any of the 16 teams which participate on the EuroCup (but with no player selection option this time).' FROM games WHERE igdb_id = 84224 ON CONFLICT (game_id, language_code) DO NOTHING;
