INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exile III: Ruined World', 'Your own party of exiles return in the final chapter of the Exile trilogy by Spiderweb Software. You''re sent to the surface world to make peace with the empire. Shortly after reaching the surface you find the world is troubled by slimes, giants, and troglodytes, to name a few.' FROM games WHERE igdb_id = 19578 ON CONFLICT (game_id, language_code) DO NOTHING;
