INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FX Fighter Turbo', 'FX Fighter Turbo is an update/sequel released for the PC in 1996 with new characters, moves, environments, costumes, special effects, network play, and support for Microsoft Windows and the S3 Graphics chipset. As are many other fighting games at the time, this game is influenced by Mortal Kombat in the form of fatalities, a feature not in the previous game. All the previous characters return, plus the new Linna and Kwondo.' FROM games WHERE igdb_id = 68982 ON CONFLICT (game_id, language_code) DO NOTHING;
