INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wishbone and the Amazing Odyssey', 'Wishbone has been zapped inside the combobulator and the only way out is to re-enact Homer''s Odyssey. The game begins in Troy, where the player picks up the crew roster and some wine. The game then passes through the cave of Polyphemus, Aeaea and Circe, Scylla or Charybdis, Thrinacia and finally home to Ithaca, where the player must win an archery contest to win Penelope.' FROM games WHERE igdb_id = 50181 ON CONFLICT (game_id, language_code) DO NOTHING;
