INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konae-chan no Doki-doki Penguin Kazoku', 'Konae-chan no DokiDoki Pengin Kazoku (KONAEちゃんのドキドキペンギン家族) is a Downloadable Event Game developed by Pax Softnica for the Satellaview. It stars Konae and was distributed as a tie in to the Radio Program "If Tomorrow Comes...". The premise of BS Konae-Chan no DokiDoki Pengin Kazoku is to cross a freezing body of water by jumping across rows of glaciers without falling into the water. Points are awarded based on the number of penguins collected.' FROM games WHERE igdb_id = 134464 ON CONFLICT (game_id, language_code) DO NOTHING;
