INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neo Mr. Do!', 'Neo Mr. Do! is a maze game released in 1996 by Visco for the Neo Geo MVS system, under license from Universal. Neo Mr. Do! plays much like the original Mr. Do! game, with players controlling the titular clown who must collect all cherries on the screen while digging tunnels and dealing with various enemies, combining elements of both Dig Dug and Boulder Dash.' FROM games WHERE igdb_id = 39540 ON CONFLICT (game_id, language_code) DO NOTHING;
