INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pebble Beach no Hatou Plus', 'Pebble Beach no Hatou Plus is the sequel to the Megadrive game Pebble Beach no Hatou that was released in 1994. Enjoy the 3D golf course set in a prestigious West Coast surrounded by the natural beauty. Pebble Beach is widely regarded as one of the most beautiful courses in the world. It hugs the rugged coastline and has wide open views of the ocean. 3D is a beautiful and faithful reproduction of the Pebble Beach golf course layout and graphic art.' FROM games WHERE igdb_id = 280945 ON CONFLICT (game_id, language_code) DO NOTHING;
