INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubble Trouble', 'Bubble Trouble''s world is filled with lusciously-drawn cartoony critters who give that cranky crab from "The Little Mermaid" a run for his money. But money isn''t what you''ll be running from: an otherwise peaceful fish bowl has been filled with bubbles that are being tossed around in an enthralling game of "Squish the Fish!"' FROM games WHERE igdb_id = 83918 ON CONFLICT (game_id, language_code) DO NOTHING;
