INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyst', 'Four million people have explored the world of Myst--and they''ve turned it into a dump. Dead animals line the docks, windows are smashed in, graffiti is everywhere, and the dignified rocket is down being used to dry clothes. Make your way through the littered landscape of Pyst, aided by the mysterious King Mattruss, and enjoy what is clearly a *parody* of a game, rather than the real thing.' FROM games WHERE igdb_id = 18920 ON CONFLICT (game_id, language_code) DO NOTHING;
