INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lovely Pop Mahjong: JangJang Shimasho', 'Lovely Pop Mahjong JangJang Shimasho is a strip mahjong game with extensively animated strip sequences. Mahjong matches are played against the members of an all female pop-band called ''VisKiss''. After defeating an opponent, the player is given the chance to play a mini-game to gain more points. Points can be spent at an item shop to buy items to help the player cheat in following rounds.' FROM games WHERE igdb_id = 130298 ON CONFLICT (game_id, language_code) DO NOTHING;
