INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soukyuu Guren-tai', 'Soukyuu Guren-tai is a vertically scrolling shooter game released by Raizing in 1996 for Arcades, with a Saturn port released in 1997. The game is unusual in that, rather than using a 3:4 aspect ratio to better suit the vertically-oriented gameplay, it uses a horizontal monitor (4:3) in the style of Neo Geo vertical shooters as well as the later Radiant Silvergun and Giga Wing. There is an English version of the game titled Terra Diver, but it was never officially released.' FROM games WHERE igdb_id = 44759 ON CONFLICT (game_id, language_code) DO NOTHING;
