INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadheat Road', 'Deadheat Road is a classic racing game in which the player compete in a racing againts a computer player car. The races usually starts in the night and ends with the daylight. The game features different cars for the player to choose and different circuits (west and east ones). The cars can also be customized.' FROM games WHERE igdb_id = 43799 ON CONFLICT (game_id, language_code) DO NOTHING;
