INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunter Hunted', 'Hunter Hunted is a side-scrolling action computer game developed by Sierra Entertainment and published on October 31, 1996. The player controls a humanoid creature (either a muscular human called Jake or a minotaur-like creature named Garathe Den) who fights enemies, completes objectives, and tries to find the hidden exit in each level. Of the two, Garathe possesses superior strength and stamina, while Jake can take advantage of more sophisticated weaponry.' FROM games WHERE igdb_id = 27204 ON CONFLICT (game_id, language_code) DO NOTHING;
