INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wave Runner', 'WaveRunner is an arcade, personal watercraft racing game. Playable with a hydraulic motion system Jet Ski that provides the realistic feel and movement of riding the waves on a 3-axis motion system. Players can turn the Jet Ski''s handle bars, moderate the accelerator, and lean the Jet Ski body with the turns on one of the three available courses (Beginner, Intermediate and Expert) . With realistic 3-D action, several tropical courses and the ability to link multiple units this is a must-have Simulator for any arcade or serious collector!' FROM games WHERE igdb_id = 39794 ON CONFLICT (game_id, language_code) DO NOTHING;
