INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aprende con Horacio: La Gran Aventura de las Palabras', '"La gran aventura de las palabras" (The Great Adventure of Words), also known as "Aprende con Horacio" (Learn with Horacio), is an educational game by the Anaya publishing house where you play with the great Horacio, Rodolfato, and Alfabeto, crossing their entire labyrinth house full of puzzles, reading challenges, and all sorts of language-related games.' FROM games WHERE igdb_id = 283755 ON CONFLICT (game_id, language_code) DO NOTHING;
