INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Schoolhouse Rock!: America Rock', 'Schoolhouse Rock!: America Rock is an educational game that teaches American history and geography for an audience of children aged six to twelve. It is based on the Schoolhouse Rock! TV series. The game story is told through a character who attempts to a get a bill passed through the House and Senate. This is done by winning five mini-games to gain approval for the bill. Eventually you make it up to Capitol Hill to have it signed into law by the president.' FROM games WHERE igdb_id = 113469 ON CONFLICT (game_id, language_code) DO NOTHING;
