INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Testament', 'Testament is a horror-themed Doom clone, set outside and inside graveyards, catacombs and dungeons filled with ancient fantasy monsters. On each level you will find a scroll, a piece of the "testament" of the title. This will allow you to save your progress and move on to the next level.' FROM games WHERE igdb_id = 100039 ON CONFLICT (game_id, language_code) DO NOTHING;
