INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Touring Car Championship', 'Sega Touring Car Championship is a Sega Model 2C CRX arcade racing game developed by Sega AM5 in 1996. It is similar to Sega Rally Championship in design, but uses touring cars instead of rally cars. Unlike Sega Rally Championship, Sega Touring Car Championship has never seen a sequel, and it considered a far less successful game for a variety of reasons, most notably the steep difficulty curve and often awkward car handing.' FROM games WHERE igdb_id = 39795 ON CONFLICT (game_id, language_code) DO NOTHING;
