INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Level-ROM', 'This unofficial shovelware add-on disc contains more than 3000 levels and utilities for :  - Command & Conquer  - DOOM  - DOOM II  - Duke Nukem 3D  - Microsoft Flight Simulator (v5.0)  - Heretic  - Hexen: Beyond Heretic  - U.S. Navy Fighters  - NBA Live 95  - The Need for Speed  - SimCity 2000  - SimCity  - WarCraft: Orcs & Humans  - Warcraft II: Tides of Darkness' FROM games WHERE igdb_id = 116804 ON CONFLICT (game_id, language_code) DO NOTHING;
