INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Slaughter', 'William Spade is an inventor that has created a ''time portal generator''. Somehow this device is sacrilegious to a race of creatures known as the Takar, and they demand it be turned over to them. Refusing to comply, he manages to vanquish these creatures from his lab, but not before losing vital body parts. He rebuilds his body and becomes the insane monster known as Portal.' FROM games WHERE igdb_id = 50082 ON CONFLICT (game_id, language_code) DO NOTHING;
