INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secret Agent: The Escape', 'Secret Agent : The Escape is a shareware Doom clone. The player takes the role of the secret agent who must shoot his / her way out of a prison complex. Initially the player starts with no weapons and has only their ninja kick to defeat the prison guards. As they progress through the maze they are able to pick up objects such as messages and weapons such as the Goo Gun.' FROM games WHERE igdb_id = 116806 ON CONFLICT (game_id, language_code) DO NOTHING;
