INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kid Klown in Crazy Chase 2: Love Love Hani Soudatsusen', '"Kid Klown in Crazy Chase 2: Love Love Hani Soudatsusen" is the sequel to the SNES title "Kid Klown in Crazy Chase". It has same gameplay, but boasts three times as many stages: the first game had five, this one has sixteen.' FROM games WHERE igdb_id = 64508 ON CONFLICT (game_id, language_code) DO NOTHING;
