INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GTI Club: Rally Côte d''Azur', 'GTI Club: Rally Côte d''Azur is a racing game originally released for the arcades in 1996 by Konami, based on PowerPC-based hardware; the player raced around the Côte d''Azur and could choose from 5 rally cars including a Mini Cooper and Renault 5 Alpine Turbo. The game allowed moderate free-roaming of the environment, which was revolutionary for the time, and contained several semi-hidden shortcuts that could be used to reduce lap times. A handbrake is provided which the player is encouraged to use to perform handbrake turns round sharp corners.' FROM games WHERE igdb_id = 28392 ON CONFLICT (game_id, language_code) DO NOTHING;
