INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('quarterback-attack-with-mike-ditka', 38828, '1996-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ltvsteisfii4fftrv0y4.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quarterback Attack with Mike Ditka', 'In this semi-fmv game you play a rookie facing his first game as starting quarterback on a fictional team, and this just happens to be The Big Game.  The entire game consists of this confrontation, upon start of the game you watch a video of a kickoff and return, and then you get to select among 110 plays (100 passing and 10 running) and assing a snap count. The meat of the game is on the passing plays, were you are switched to a 3rd person behind-the-quarterback view from which you can see oncoming rushers as well as zoom in on any receiver and via a targeting cursor make passes, or scramble if you don''t find any open man, etc.' FROM games WHERE igdb_id = 38828 ON CONFLICT (game_id, language_code) DO NOTHING;
