INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Potestas', 'Potestas is a political simulation game that takes place in a fantasy land. The player can check every part of the land to know what the people of each part of the land needs and try to solve their problems, after checking in each turn he got to take different decisions and depending of their choices all of them got to be taken to the parlament where there will be a voting, if the action is elected it will be done.' FROM games WHERE igdb_id = 123267 ON CONFLICT (game_id, language_code) DO NOTHING;
