INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek Klingon', 'In this holodeck adventure, you are Pok, a young Klingon warrior caught up in the dangerous circles of Klingon clan politics. On the day of your Rite of Ascension, your father is murdered in his own home. It is up to you, with the help of Gowron, leader of the Klingon High Council, to find the murderer and close the circle of vengeance. Along the way you will encounter strange aliens and treacherous friends and even serve aboard the mighty Bird of Prey, the Tagana.' FROM games WHERE igdb_id = 51380 ON CONFLICT (game_id, language_code) DO NOTHING;
