INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Weird: Truth is Stranger than Fiction', 'Throughout the centuries, people have always been fascinated by tales of the supernatural, mysterious or unearthly characters, inexplicable occurrences beyond scientific explanation, and mythical creatures outside civilization. Incredibly, some of these otherwise unbelievable stories are supported by factual evidence. As you open your mind and challenge the way you think about the world, expect the unexpected.' FROM games WHERE igdb_id = 69217 ON CONFLICT (game_id, language_code) DO NOTHING;
