INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Timmy the Dream Hunter', 'Timmy the Dream Hunter is an interactive storybook which follows the kid Timmy and how he manages overcome his fear of the night. Each of the 15 panels is introduced with a narration and afterwards the player can click on items or persons to trigger animations. Each panel also holds a simple hidden mini game, e.g. matching the arm positions of a goblin or drawing a star constellation by clicking on spots in the given order.' FROM games WHERE igdb_id = 307299 ON CONFLICT (game_id, language_code) DO NOTHING;
