INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vegas-casino--2', 79373, '1996-09-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob4bf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4zd2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vegas Casino', 'Known as "Super Casino Special" in Japan, Vegas Casino is a game for up to four players via multitap comprising Baccarat, Roulette, Let It Be, Black Jack, Video Poker, Keno and Slot Machines. It can be played in two modes, Ranking play or Free Play. In Ranking mode the player enters a target amount to be reached and then plays against their opponents to see who can reach that amount. If a single player plays in this mode the game provides three opponents but the game caters for up to ten players with the game providing the additional AI opponents. Roulette,Video Poker, and Slot Machines in this game mode are played within a split screen. In Free mode there are no computer opponents and the games are the same as the games played in Ranking mode though there are minor differences, such as selecting which slot machine to play, because in this mode the split screen mode is not used at all. There are three kinds of slot machine which can be played for different stakes. Keno is the odd game here because it does not appear on the game menu, instead during any game other than Video Poker a casino hostess pops up in her own little window inviting the player to a game of Keno. If the player accepts they are shown a Keno card on which they mark their numbers after which their current game of Baccarat, Roulette or whatever resumes. A short while later the hostess window opens up again and the hostess gives the good, or more usually bad, news on how good their selections were.' FROM games WHERE igdb_id = 79373 ON CONFLICT (game_id, language_code) DO NOTHING;
