INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gungriffon', 'The Gun Griffon armored mechanoid is the most sophisticated military hardware yet to grace the battlefields of the 21st century. As a leading commander of the Asian Pacific Community''s army, you control a devastating array of weapons in your bid to smash the enemy''s defenses and destroy their key strategic targets before time runs out.' FROM games WHERE igdb_id = 46054 ON CONFLICT (game_id, language_code) DO NOTHING;
