INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '15x15', 'A collection of sliding picture puzzles. You can chose from 3x3 or 4x4 grid sizes and select from several pictures, you unlock more as you go. You are scored based on how many moves it takes to complete a puzzle starting with 999 for the 4x4 and 499 for the 3x3 puzzles and counting down.' FROM games WHERE igdb_id = 109473 ON CONFLICT (game_id, language_code) DO NOTHING;
