INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X2', 'X2, sometimes known as Project X-2 or X2 - No relief is a simple arcade-style side scrolling shoot ''em up released during the Team17-Ocean collaboration era of video games that created the Worms series. It is the sequel to the Amiga 16-bit shooter Project-X. Unlike its predecessor, the game was a console exclusive. A Sega Saturn version of the game was scrapped during development.' FROM games WHERE igdb_id = 79811 ON CONFLICT (game_id, language_code) DO NOTHING;
