INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei: Devil Summoner - Akuma Zensho', 'Translating to demon compendium, this Sega Saturn disc is supplementary content to Shin Megami Tensei: Devil Summoner, releasing a few months after the game on April 26th, 1996. It was later packaged in a bundle with the original game in the Special Box re-release. It allows the player to view artwork of Devil Summoner''s 255 demons and read about their stats and backstory while listening to music.' FROM games WHERE igdb_id = 145827 ON CONFLICT (game_id, language_code) DO NOTHING;
