INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alice in Cyberland', 'Adventure game released exclusively on Playstation. Alice in Cyberland takes place in a futuristic setting where the internet has evolved into a VR environment called Cyberland. Alice, Julie and Reina are three high school girls who can dive into this virtual world and they are tasked with defending it from hackers and other forces trying to take over. The main portion of the game is played through VN styled dialogue and interaction screens, where you choose from two to 4 choices of available routes that you may take. The game also has a battle system, in a fully 3d environment, that is basically rocks-paper-scissors.' FROM games WHERE igdb_id = 69003 ON CONFLICT (game_id, language_code) DO NOTHING;
