INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Soccer', 'A football game developped by Lobotomy Software in 1996 and published by Microsoft. There is in total 92 teams in the game (only national teams) although all the players are fictitious. In single player the game offers a single game or a tournament (a cup with up to sixteen teams). Single games can also be played with up to four friends in multiplayer via LAN, Internet or modem. Also included is a team editor that allows the user to modify the teams or create new ones.' FROM games WHERE igdb_id = 93003 ON CONFLICT (game_id, language_code) DO NOTHING;
