INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toxic Bunny', 'Toxic Bunny is a side-scrolling action platform game for MS-DOS computers released in 1996 by Celestial Games. The game covers four large levels in which Toxic hunts the person (or animal) responsible for interrupting his coffee break, brainwashing all his friends, and covering the planet with a decaffeinated goo. Within the game you can use any number of incredibly large weapons including a Nitric Hamster Launcher, while squashing aliens with rusty nautical equipment. The game has been called a psychedelic parody of Epic Games character, Jazz Jackrabbit.' FROM games WHERE igdb_id = 145523 ON CONFLICT (game_id, language_code) DO NOTHING;
