INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dyna Blade', 'Dyna Blade is the second main game featured in Kirby Super Star and its remake, Kirby Super Star Ultra. In this game, Dyna Blade, a large bird with metal wings, has stolen crops from local farmers. Kirby must go through four levels and two hidden areas, before finally fighting Dyna Blade herself.' FROM games WHERE igdb_id = 271260 ON CONFLICT (game_id, language_code) DO NOTHING;
