INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Revenge of Meta Knight', 'Revenge of Meta Knight is the fifth main game in Kirby Super Star and its remake. This game takes a much more serious tone than the other games in the collection, and tasks Kirby with stopping Meta Knight and the Meta-Knights from taking over Dream Land using their giant ominous flying warship, the Halberd.' FROM games WHERE igdb_id = 271263 ON CONFLICT (game_id, language_code) DO NOTHING;
