INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shingata Kururin Pa!', 'Competitive puzzle game where the player places rope pieces. Once ready, drop a flame to ignite! This starts a burning chain reaction, clearing blocks and mucking up the opponent''s board with snowballs. Choose from a myriad of diverse and colorful characters, each possessing a unique piece that will help in the game. Released in Japan on Saturn and Playstation by Sky Think System.' FROM games WHERE igdb_id = 228065 ON CONFLICT (game_id, language_code) DO NOTHING;
