INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Invention Studio', 'Invention Studio is an educational game made for kids nine and up. In the game you can brainstorm then build gadgets, electronics, air and land vehicles then test them out to see how they fair. Once your creation is working and tested you can patent your invention and even print the patent. Invention Studio also includes an in-game Notebook/Sketchbook, some other mini-games as well as short videos about brilliant inventions and inventors.' FROM games WHERE igdb_id = 100254 ON CONFLICT (game_id, language_code) DO NOTHING;
