INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('death-crimson', 54917, '1996-08-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co688d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scyp5l.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Crimson', 'Death Crimson is a first-person rail shooter released exclusively in Japan. The game is a light gun shooter that attempted to capitalize on the growing popularity of the genre during the mid-1990s console era. Infamous in the Japanese gaming community, the game is celebrated as a prime example of a "kusoge", notorious for its abysmal graphics, frustrating hit detection, and disorienting camera.' FROM games WHERE igdb_id = 54917 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 54917 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
