INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Fire', 'In Black Fire, the player takes control of the most sophisticated helicopter on the planet taking on a very dangerous enemy. The player''s helicopter is state of the art, but the enemy they are fighting has acquired alien technology and is using it to try and conquer the world and it is up to the player to use all the flying skill they have and try to stop them.  Black Fire is rendered in 3-D and has a 360 degree field to maneuver. The chopper is outfitted with missiles and machine guns and flies through 15 levels, destroying enemy targets and providing support to allied units with the story told through CGI cutscenes.' FROM games WHERE igdb_id = 46087 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 46087 AND p.igdb_id = 32 ON CONFLICT DO NOTHING;
