INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('deus', 10858, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4m31.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvna.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deus', 'Deus is a survival Simulation Game, and the sequel to Robinson''s Requiem. The player again assumes the role of Robinson''s Requiem protagonist Officer Trepliev, who has become a bounty hunter for the Alien World Exploration department. The player''s goal is to save a scientific research station from a group of terrorists called the New Crusaders. Like Robinson''s Requiem, the game features complex health monitoring and surgery systems; however, the game now contains an optional "action mode", which removes these systems.' FROM games WHERE igdb_id = 10858 ON CONFLICT (game_id, language_code) DO NOTHING;
